quests[66015] = { id = 66015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blue Dragon Oathstone", description = "The Azure Span has stabilized for now and more blue dragons have arrived... just in time.\n\nIt's time to return to the Azure Archives and reclaim the oathstone.\n\nI would request your presence there, {name}. You've been a great boon throughout this ordeal.", progress = "I'm quite relieved you all prevented the complete annihilation of the Azure Span.\n\nShall we continue?", completion = "The Oathstone is empowered once more. There is much to do... but the Azure Span is at least returning to what it once was.", objectives = "Accompany Kalecgos to claim the Blue Dragon Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66016] = { id = 66016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Teerai", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nClan Teerai is the clan of our Khanam Matra, our direct connection to the Maruuk ancestors. They are the holders of our traditions, and our storytellers.\n\nTo understand the Maruuk, you must understand Clan Teerai. One of the Khanam Matra's daughters, Qariin Dotur, is preparing a meal for our ancestors. Aid her. She will teach you about our people.", completion = "Welcome, outsider.", objectives = "Report to Qariin Dotur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66017] = { id = 66017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Ohn'ir", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nThe mystics of our lands, like Ohn Seshteng, belong to Clan Ohn'ir. The clan is not made up of families, but rather of centaur from across the plains with an innate connection to Ohn'ahra. They spend their lives building that connection and honing their skills. Eventually, they receive assignments to advise different clans and protect our lands.\n\nOhn Seshteng went to speak with her khan about the omen she received. Join her to learn about the Ohn'ir.", completion = "It is good to be back with my clan.", objectives = "Meet Ohn Seshteng at the mystic pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66018] = { id = 66018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Nokhud", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nClan Nokhud is the newest to rise to power. Their late khan, Jhakan, raised a mighty army to seize territory from their predecessors. Such is the way of our people.\n\nWhile Jhakan had earned his respect, his son has not. Balakar killed his father and took control of the clan. They have grown ever more insular since. But to know the Maruuk, you must know them.", completion = "I have the great unpleasantness of introducing you to Bahir, one of Balakar Khan's thugs.", objectives = "Accompany Tomul to Guard Bahir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66019] = { id = 66019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring Our Ancestors", description = "Our ancestors walk beside us upon the winds of Ohn'ahra, guiding and protecting us. All Maruuk, dead and living, gather under truce at the Khural. \n\nThe scent of this meal calls the ancestors to our fire. When they arrive, the Khural begins.", progress = "The Maruuk have returned to this spot for generations upon generations. We walk alongside our ancestors.", completion = "Our ancestors risked much for our future. It is right to invite them to gather alongside us.", objectives = "Help Qariin Dotur cook a meal for the ancestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66020] = { id = 66020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omens and Incense", description = "I shared with Tigari Khan the omen we received before entering Maruukai. She expressed her concern, as the wind felt cold to her as well.\n\nWe cultivate certain flowers here, blooms that can be ground and burned to elicit a trancelike effect. They are used to deepen our connection to an omen. \n\nI request that you collect some so that we may make an incense to burn. With my khan's help, perhaps we can learn more of Ohn'ahra's plight.", progress = "Tigari Khan is most well-versed in reading omens. With her aid, we can learn more about this omen.", completion = "A betrayal threatens Ohn'ahra herself. We must stand tall, {name}. Now is a time for allies.", objectives = "Collect 5 Sweetsuckle Blooms, grind them into Sweetsuckle Incense, then aid Ohn Seshteng in the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66021] = { id = 66021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Outsider", description = "Hah! Look at you. Weak. Just like those puny hunters that brought you here.\n\nYou want to know the Nokhud? We speak through battle. \n\nOur battle ritual is called \"the tabarr\". We train. We spar. And it hardens us. Now there is no weakness in our clan.\n\nEnough talk. Go spar.", completion = "The Nokhud prefer brute strength and power over all else.\n\nWe do not see eye to eye on many things.", objectives = "Defeat 6 Nokhud centaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66022] = { id = 66022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Khanam Matra", description = "I cannot linger in centaur lands; I must return to the gardens as soon as I am able.\n\nThe Khanam Matra has agreed to hear our plea for aid. She awaits my arrival at the top of the krutal, the central building of Maruukai.\n\nThough I must speak with her on my own at first, you are more than welcome to join us.", progress = "The Khanam Matra is waiting for you.", completion = "That traitorous fool.\n\n<Akato spits on the ground.>", objectives = "Report to Khansguard Akato to join Gemisath's audience with the Khanam Matra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66023] = { id = 66023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trucebreakers", description = "Balakar disgraces his clan. He leads them into the storm, blinded by his lust for power.\n\nTheir betrayal reveals their fragility. Cut them down.", progress = "To attack the Khanam Matra... it is a rejection of our ways.", completion = "The path they have chosen is now stained with blood.\n\nScout Tomul tried to warn us this might happen. She may have further suspicions.", objectives = "Kill 10 Nokhud forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66024] = { id = 66024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covering Their Tails", description = "The Nokhud drool over war stories of our kind's ancient past. In truth they are weak, playacting children. And with one strike of lightning, they have severed their connection to Ohn'ahra.\n\nWell! If they will walk the path of corruption to seek war, then we will indulge them.\n\nOf course, Bahir was left in command to cover his escape. Her blood will soon stain the ground.", progress = "<Sarest surveys the battlefield, eyes narrowed.>", completion = "Balakar was an easy target for Koroleth's corrupting influence.\n\nThe storm has arrived.", objectives = "Slay Guard Bahir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66025] = { id = 66025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nokhud Threat", description = "Clan Nokhud's army is taking Maruukai. \n\nLet us discuss our next moves in the khan chambers. We must keep the Maruuk safe.", completion = "The very lifeblood of the Maruuk is in danger.", objectives = "Discuss next steps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66026] = { id = 66026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Action Required", description = "The source of these attacks must be the Brackenhide.\n\nWe've fought with the Brackenhide gnolls for generations, but until now they've been nothing more than a nuisance.\n\nWe have no choice but to take urgent action against the gnolls. Their foul decay will destroy the Azure Span, including whatever you're searching for.\n\nMeet us outside Brackenhide. We will need all the help we can get.", completion = "Just standing here, I can feel the dread of this forest wash over me. Something is deeply wrong here. \n\nI'm beginning to regret sending our best fighter back to Iskaara.", objectives = "Meet Brena at Brackenhide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66027] = { id = 66027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling the Blue Dragons", description = "I can no longer be afraid of reuniting the blue dragons, {name}. It is better for us to be a family... than a fragment of our former selves.\n\nEven if I cannot reclaim the oathstone, I can still use its power to send a message to all of the blue dragons. \n\nIt is time they received word... from their Aspect.", progress = "Stand back, {name}.", completion = "We need to move, {name}.", objectives = "View Kalecgos call back the blue dragonflight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66028] = { id = 66028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Future!", description = "I have tracked Chronormu and Eternus to a potential future. I know not what you will find there, only that it is dark and chaotic.\n\nSoridormi has taken some of our timewalkers ahead to that future in order to hold our connection to that time stable. Her considerable power will be needed to keep the portal open, so she must rely on your talents.\n\nSoridormi will be able to direct you further once you meet her there.\n\nHurry, {name}. Find Chronormu.", completion = "We need to find Chromie and Eternus before more damage can be done to this time.", objectives = "Travel to the Primalist Future.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66029] = { id = 66029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Tuning", description = "Chronormu and Eternus are falling though time, but I sense them stop every so often. These brief moments are our opportunity to find them.\n\n<Nozdormu conjures a small chrono crystal.>\n\nI have imbued this crystal with power as well as my own temporal resonance. They have gone to a... troubling possible future. Find them and use it. Hopefully you can fix their position in time before they slip away again.", completion = "The process was not finished but I can more accurately track Chronormu now.", objectives = "Use Chrono Crystal on Eternus and Chromie in the Primalist Future to stop them from falling through time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66030] = { id = 66030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resistance Isn't Futile", description = "The temporal ripples have caused trouble for the people here. Enemies appear where they were not, or are far stronger than they should be. These changes are small, but they are disastrous.\n\nI ask you to help the resistance fighters here. Heal their wounds so that they may fight once more. Set their timeline back on its correct course, as if it had never interacted with our own. It is not much, but it is what we can do for them.", progress = "Have you assisted the resistance?", completion = "These brave fighters will be able to bolster their forces once more.", objectives = "Heal resistance fighters in the Primalist Future.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66031] = { id = 66031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Time", description = "I guess I shouldn't be surprised to find myself here.\n\nThis is not the Azeroth I wanted, but it's the one I have. We're fighting to preserve what's left and take the world back, but your arrival has caused some trouble. \n\nWe use the essence of those elementals out there to fuel our protections and keep ourselves safe. See that shield? That's the only thing keeping us from discovery and annihilation and you drained our resources. Bring back some of that essence and we may survive another day.", progress = "Have you collected what we need?", completion = "You've given us some breathing room.", objectives = "Collect Elemental Essence for the survivor's camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66032] = { id = 66032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Present", description = "This timeline is dark and chaotic. The disruption here has been severe. I shall remain in this timeline a moment more to help sort out what remaining ripples may appear. \n\nReturn to Nozdormu. He will want to know of our success, even if it was less complete than we would like.", completion = "Your journey did not accomplish our goals, but it was a success nonetheless.", objectives = "Return to Nozdormu in the Present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66033] = { id = 66033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the... Past?", description = "It is regrettable that we could not stabilize Chronormu, but there is another potential location where we may be able to catch her and bring an end to her fall through time. \n\n<Nozdormu frowns.>\n\nThe glimpses of this timeline past are... strange. Even among some of the visions I have witnessed in my life.\n\nBe on your guard, {name}. I am uncertain what you will face, but it is powerful and... oddly familiar.", completion = "Whatever I expected... This is not it.", objectives = "Take the portal and meet with Andantenormu in Azmerloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66035] = { id = 66035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Motes", description = "An alternate timeline born from murlocs??!\n\nForgive my selfishness, but would you obtain a few stray motes of temporal energy while you locate Ambassador Chronomu? \n\nJust walk into them and your staff should do the rest. I will examine the data later. When we are not in the middle of venturing through rips in Azeroth's varied realities.", progress = "I have no doubt we shall succeed against the Infinite this day, and studying this foreign energy will be our reward!", completion = "Astounding work! \n\nNow, what do you imagine the murlocs of this Murloc World are? I shudder to think...", objectives = "Drain 12 Temporal Motes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66036] = { id = 66036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", progress = "Murglgulglrrlglgul!", completion = "Frrg thrg Allrghnnge!\n\n<The murlocs appear to be pleased.>" }
quests[66037] = { id = 66037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Reality", description = "We were able to increase Ambassador Chronormu's connection to our time. I am certain when we find her again, we will be able to finish the ritual.\n\nFor now, let us return to our present and a world with... significantly fewer murlocs.", completion = "Thank you for helping to uphold the timelines... odd as they may sometimes be.", objectives = "Return to Nozdormu in the Present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66038] = { id = 66038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Race Through Time!", description = "{name}, we must act quickly to catch up to Ambassador Chronormu, and I mean that quite literally.\n\nZera and I will do what we can to speed our progress, but it is imperative we avoid entangling with this time period as much as possible. To do so will slow us down and we may not be able to catch the Ambassador before she is lost to even Nozdormu's magic.\n\nWe haven't a moment to lose!", completion = "By the Aspects... This is the Black Empire!", objectives = "Race through time, following Chromie and Eternus's Path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66039] = { id = 66039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie Time", description = "This... This is the Black Empire. We have traveled very far into the past, indeed.\n\nLook! I see Ambassador Chronormu and Eternus! We need to hurry and complete the ritual. \n\nEven my curiosity is not enough to wish to see where they might travel to next.", completion = "That feels much better!\n\nOh, don't worry about Eternus. We've come to a bit of a truce for the moment.", objectives = "Find Chromie and Complete the Temporal Stabilization Ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66040] = { id = 66040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Future", description = "We're not going to fall through time anymore but we're far in the past. Waaaaay far in the past. \"The Titans Haven't Visited Azeroth Yet\" far in the past. Getting home is going to be... tricky.\n\nBut we dragons can do it! \n\nWe're going to need you to keep those Black Empire minions off our backs though. It shouldn't take too long! \n\nI think.\n\nProbably.\n\nDon't worry about it! Just keep those creepy monsters away and we'll handle the rest! Easy!", progress = "This has been an... unexpected turn of events.", completion = "Time is stable once more.", objectives = "Defend your allies against the Black Empire until the temporal portal is created.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66042] = { id = 66042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patterns Within Patterns", description = "We stand at the origin of the Shadowlands. We must not allow this place to become its undoing.\n\nWork with our new allies, {name}. Their assistance will be the difference between our success and the unmaking of all things.", progress = "In this place, all fates are intertwined.", completion = "We move closer to our goal. Ever onward.", objectives = "Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66044] = { id = 66044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Walls", description = "Sabellian and the other dragons are holding back the djaradin for now. We must act quickly to secure the high towers and ensure our victory.\n\nYou and I shall clear the siege arbalests that threaten us from above.\n\nLet me know when you are ready.", progress = "Are the Arbalests and Champion Choruk defeated?", completion = "Well done, {name}. Sabellian and his forces will hold off the djaradin, while I activate the Oathstone to restore power.", objectives = "Eliminate the three Siege Arbalests and Champion Choruk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66048] = { id = 66048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Plans and Intentions", description = "Attacking the djaradin controlling the Obsidian Citadel will be no easy task. Even with Wrathion and his Blacktalon forces, this will be a fierce battle. Wrathion may be confident, but... I am not so certain.\n\nPerhaps we can speak to those helping to plan the strategy, and see if we can find any room for improvement.", progress = "Can you improve our odds of success?", completion = "I see. I shall consider your evaluation carefully, of course.", objectives = "Review the plans with the various members of Wrathion's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66049] = { id = 66049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidian Oathstone", description = "When Neltharion became the Earth-Warder, he swore an oath to protect this world, {name}. To safeguard the deep places of the earth and, with his flight, to serve as Azeroth's defenders. The Obsidian Oathstone represents that promise. \n\nWe must activate the stone and let the Dragon Isles know that the black dragonflight has returned!\n\nFollow me, {name}.", progress = "Have you seen the Oathstone?", completion = "This is a setback, but with your help, I am sure we can repair the Oathstone. Work with Bazentus... make it so.", objectives = "Locate the Obsidian Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66055] = { id = 66055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Past", description = "The Oathstone is damaged! There are pieces missing.\n\nDo what you can to recover the fragments... maybe there is a way to fix the stone!", progress = "Have you found the missing fragments of the Oathstone?", completion = "This looks like all the pieces. I believe we can repair this!", objectives = "Recover 12 Oathstone Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66056] = { id = 66056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a New Future", description = "The forge of the Earth-Warder is the most powerful of all the dragon forges in existence. Our ancestors used it to create the strongest weapons and armor to defend Azeroth.\n\nWithin the hearth of that forge is the power necessary to reform the shattered fragments of the Oathstone.\n\nLet us go and prepare the forge for the work to be done.", progress = "Have you finished the work we require?", completion = "Very good. Now with the arrival of our Prince, we can begin.", objectives = "Prepare the Earth-Warder's forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66057] = { id = 66057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Faith", description = "The shattered fragments have been reformed. We are ready to repair the Oathstone.\n\nGo now and help Wrathion complete the repairs.", completion = "This complicates matters, but I will not be denied what is rightfully mine!", objectives = "Repair the Obsidian Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66070] = { id = 66070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brightblade's Bones" }
quests[66071] = { id = 66071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Rocs", description = "The name is Professor Harleen Chirpsnide, infamous ornithologist extraordinaire! I came here to study the mythical bluefeather rocs of the Dragon Isles, but I suppose we've got bigger fowl to fry.\n\nI bet these harpies flew in from Kalimdor when the Isles opened up. They're highly invasive and feasting like a pack of ogres at the Bilgewater Casino buffet.\n\nLet's give the native rocs here a fighting chance. Take this medical kit and use it to get the injured ones back on their feet.", progress = "Don't worry about using up my supplies. I'm good pals with the clerks at the Expedition's reimbursement office.", completion = "A full-feathered job, {name}!\n\nI would have helped you with the healing and the slaying, but I'm more of an 'ideas goblin' these days.", objectives = "Assist 8 Injured Bluefeather Rocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66074] = { id = 66074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Scythid Queen" }
quests[66076] = { id = 66076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Name" }
quests[66078] = { id = 66078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharp Practice", description = "For years I have fostered the Blacktalon, teaching and encouraging them to pursue the same heights you have reached.\n\nThey may not have achieved the same lofty goals as yourself, but they are accomplished in their own right. They've made me proud.\n\nEach would be honored if you test their skills. I think you will see some of yourself in them.", progress = "Have you tested them and found them worthy?", completion = "I believe the Blacktalon are prepared for anything.", objectives = "Test the skills of 8 Blacktalon Assassins and Avengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66079] = { id = 66079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrathion Awaits", description = "These eggs represent a new generation of dragonkind. They must be protected and fostered. Yet... my heart aches, and I worry for Wrathion. I fear his stubborn determination will lead to folly. \n\nYou have been a trusted friend over the years, {name}. Perhaps you can go in my place, and help him. \n\nSeek him out at the Obsidian Bulwark. And please, watch over him. There are so few of his flight left.", completion = "Ah, champion--your arrival is most fortuitous. With you here now, my plan will certainly succeed.", objectives = "Meet with Wrathion at the Obsidian Bulwark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66080] = { id = 66080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Difficulties", description = "Hello, {class}. You're right on time!\n\nSome trouble up at the temple is causing the timeways to destabilize and spill out into the valley. Not only that, but a bunch of Timewalkers are missing!\n\nWe've asked for extra help, but one of the new recruits hasn't arrived yet.\n\nCan you look for her? Be careful though, time's in a massive state of flux around the valley. There's no knowing what dangers are around!", completion = "I knew somebody would come around... eventually!", objectives = "Find the missing recruit in the Flowing Forest in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66081] = { id = 66081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is Running Out", description = "With the bronze temple under attack temporal energy is seeping out everywhere.\n\nThe Timewalkers placed collectors all through this forest trying to gather all the errant magic. Anything collected can also be used as extra power! Which is a good thing, this crisis is draining all our resources.\n\nI was supposed to retrieve the collectors, but I still need a moment to catch my breath.\n\nCould you get them for me?", progress = "Were you able to find them all?", completion = "Thank you, {name}. \n\nNow the forest can try to recover, and the Timewalkers have extra some extra energy.", objectives = "Collect 8 Temporal Collectors in the Flowing Forest of Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66082] = { id = 66082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time in a Bottle", description = "Great! The Timewalker staff intact! But, it is definitely drained.\n\nI know! You can recharge it using the temporal energy coalescing around the wildlife here. Unfortunately, that means defeating affected creatures in the forest. The energies were making them dangerous and unstable, and we would have had to cull the population after anyhow... \n\nSometimes you have to sacrifice for the greater good. Could you help? I still need a minute.", completion = "This staff has been through a lot, but it should be fully functional again.\n\nThank you, {class}.", objectives = "Collect time energy from slain time-charged wildlife within the Flowing Forest of Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66083] = { id = 66083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feels Like the First Time", description = "Shepherding the timeways is a dangerous duty.\n\nThough you are not a Timewalker, Ambassador Chronormu believes you will be of great help. But to ensure your safety we must properly train you.\n\nUnfortunately, all our instructors are still missing. I will do my best to help. Let us see how we both do. I know the Ambassador Chronormu is counting on the both of us.", completion = "That was quite unexpected! As you can see, there are many dangers that come with wielding time energy.\n\nI do wish there was time to examine the effects of your little hiccup, but there are more important matters.", objectives = "Speak with Andantenormu and participate in Timewalker training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66084] = { id = 66084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Times Like These", description = "Despite that small hiccup during training, I believe you are prepared enough to aid us here.\n\nThe distortions in the valley are allowing different time periods to cross over into ours. We are unsure why these timelines connect which is quite alarming. We need more information.\n\nPlease, see if you can find anything about the creatures pouring in from different timelines. I am sure their passage will have left some sort of residue. By studying it we can hopefully find a way to get ahead of this crisis.", progress = "While it is unfortunate this is all happening, I am eager to discover new chronologies to study.", completion = "With these samples, we will have a better understanding of how and why these timelines are intersecting with ours.\n\nThank you for your assistance.", objectives = "Collect 100 Temporal Residue from time-lost enemies in the Shifting Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66085] = { id = 66085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If We Could Turn Back Time", description = "A proper Timewalker never leaves a crisis half-resolved. Why wait and study when we have the tools we need already?\n\nSince you have my original staff, I found a spare for me to use. I am sure no one will miss it. This is my plan: we team up on those rifts together and save the day! All the days, really. Sorry, I still get confused about the time stuff. \n\nWhat do you say? The task should be simple enough, right?", completion = "We did it! Right?\n\nOkay maybe there was a wrinkle or two--nothing Dante needs to know about. Also, an unexpected visitor..\n\nStill, overall I would say that went pretty well.", objectives = "Close the Time Rifts in the Shifting Sands with Siaszerathel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66087] = { id = 66087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closing Time", description = "These incursions push the durability of this timeline to the point of breaking. If only we had our full contingent of Timewalkers!\n\nThough you are a novice with the staff, I am told that you have managed to help us out greatly. With an extra push, I believe you may further aid our cause.\n\nNormally, I would put you through a full training but the times are... unorthodox. Take this scroll of advanced knowledge and use it to push back the invaders! Be swift though, the effects are only temporary.", progress = "Every incursion threatens to weaken this timeline.", completion = "A Timewalker's staff is crucial to shepherding time. Sometimes a gentle prod is all that is needed. Other times, firmer action is required. This should be enough to mitigate the instability in this area for now. \n\nWhile there is still more work to be done, your companions are eager to assist up at the temple. I will ensure the area down here is supported while you all go ahead.\n\nGood luck.", objectives = "Assist the Timewalkers by slaying time-lost enemies, buffing bronze allies, returning lost artifacts, and closing time rifts in the Shifting Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66090] = { id = 66090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Dark Rangers", completion = "<Velonara peers at you knowingly.>\n\nIt was a fair disguise, but I saw at once that you were not who you claimed to be. \n\nRegardless, you risked your life to aid us. I will not forget that.\n\nThere are those among the kaldorei raised by Sylvanas' val'kyr who wish to return to their own. If Tyrande would have them back, they are free to go. The rest will be welcome in the ranks of the dark rangers. \n\nIn recognition for your service to us, I offer this gift.", objectives = "Accept the Dark Ranger regalia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66091] = { id = 66091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Dark Rangers", objectives = "For years, we dark rangers worked as agents of the Banshee Queen. Now, under the leadership of the new Forsaken council, we serve a greater cause: shaping our people's future.\n\nWe cannot be certain what lies ahead. But I vow that the dark rangers will do everything in our power to defend this kingdom.\n\nYour aid was crucial in helping us cleanse the ruins of Lordaeron. Take this, with our thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66094] = { id = 66094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Szar Skeleth", description = "According to the watcher's logs, the stone of Insight can be found in a draconic tower on a river in the center of the Ohn'ahran Plains. That should be Szar Skeleth. Be careful. We can be sure the Sundered Flame won't let us just walk in and take it.\n\nOnce you get there, rendezvous with Toddy. Then we can retrieve the stone.", completion = "Ye made it. I've quite the mission for ye, {name}.", objectives = "Meet up with Toddy near Szar Skeleth in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66100] = { id = 66100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplying in Weight", description = "I really screwed up this time. I only stepped away from the campsite for a moment, but I barely returned in time to see the tarasek snatching up everything I had not bolted down.\n\nThose supplies were expensive, and I can't exactly ask for help getting more! My sister Nori thinks I'm inept enough as it is.\n\nIf you are sure you want to head through the valley, would you mind keeping an eye out for any stray bags of supplies?", progress = "<Alvi glances in your direction, clearly panicked. The missing supplies seem to be the last thing on her mind at the moment.>", completion = "Thank you, {name}, but we have bigger things to worry about now.", objectives = "Collect 6 bags of Waywatcher Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66101] = { id = 66101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Such Great Heights", description = "Toddy and Naleidea have requested a survey report of the surrounding area immediately.\n\nLuckily, I have acquired an enchanted telescope and surveyor's disc that will help us scout out nearby areas from the safety of the clouds.\n\nUnluckily, I am deathly afraid of heights and cannot bring myself to set foot on the contraption.\n\nYou are not afraid of heights, are you?", progress = "Good luck up there. I much prefer the ground under my feet.", completion = "<Aster breathes a sigh of relief.>\n\nI thought for certain you would plummet to your death from up there. Thanks again for taking the risk so that I was not required to.", objectives = "Use the Surveyor's Disc to bounce into the sky and scout the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66103] = { id = 66103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eager to Please", description = "We need more troops to defend the Obsidian Citadel. Now that we've got a foothold, it's important to make sure we've got fresh eyes and bodies for the effort.\n\nWe have additional reserve troops at the Obsidian Bulwark that could reinforce us.\n\nThey are well trained, but they'd benefit from a combat test with someone as skilled and experienced as you. So we know they're ready.", completion = "Thank you, {name}. These troops are better prepared than ever, thanks to you. And this effort will take a lot of preparation and muscle.", objectives = "Test the skills of 10 Blacktalon Assassins and Avengers at the Obsidian Bulwark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66104] = { id = 66104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensic Ecology", description = "I'm at my wits end, {name}. Tharu and I have made our way through nearly all the corpses only to stumble at the end because we cannot agree on a methodology. If only he would just listen to me!\n\n<Ecologist Iskha sighs.>\n\nThe stress of the situation is getting to us both. I don't even have a firm hypothesis yet.\n\nYou look like you have a strong stomach. Will you take over on these last two gorlocs? You can borrow my scalpel.", progress = "Don't worry, you'll get used to the smell after a while.", completion = "It's the gorlocs fighting that's been harming the wetlands so?\n\n<Ecologist Iskha looks ashamed.>\n\nI think I understand now...", objectives = "Dissect the gorloc corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66105] = { id = 66105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scalpel of a Solution", description = "I believe we are gathering enough data safely from here but... \n\nTharu is an exceptional ecologist and prefers we take action. Still, the ecosystem is fragile, and we may damage it if we are not careful. I do however agree we don't have much time. \n\nIt might be worth indulging him. A little.\n\nCulling the rampaging elementals ought to buy us time without impeding our research. Be sure to cull them in equal numbers--we don't want to throw things further out of balance.", progress = "Is it done? Can I finally get Tharu off my back about this?", completion = "Did that seem to affect anything? No?\n\n<Ecologist Iskha sighs.>\n\nWell, at least we're nearly finished with our research.", objectives = "Kill 5 Rampaging Water and 5 Rampaging Wind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66106] = { id = 66106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Be So Shellfish", description = "I was a fool to doubt Iskha when he insisted there was more to this. He wouldn't be my mate if he wasn't always two steps ahead of me.\n\nWe can make it up to him--by taking action, of course. If it's shells that are causing all this elemental chaos, why don't you go into their camp and take those shells right out of their slimy hands?\n\nBring back piles of the wind and water shells, enough for Iskha to research to his heart's content.", progress = "That ought to show them.", completion = "Iskha and I will take these back to the life pools--somewhere where they can't cause any more trouble.\n\nYou've done good work here today, {name}.", objectives = "Collect 15 Water-Infused Shells and 15 Wind-Infused Shells from Soggymaw and Windyfin Gorlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66107] = { id = 66107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlife Rescue", description = "It doesn't take an ecologist to see that the wetlands are in real trouble.\n\nBut Iskha's got us stuck here examining dead creatures when we ought to be stopping them from dying in the first place! The red dragonflight is about preserving life--not dissecting it!\n\nI love Iskha, and he's good at what he does, but if we wait until he's done puttering, there won't be any wetlands left to save. \n\nI'll manage his overthinking. You get out there, get your boots muddy, and rescue some wildlife.", completion = "There! The wetlands are fixed! Meanwhile, Iskha is still doing his taxidermy... I mean research!\n\nWait, what do you mean the elementals keep coming?", objectives = "Rescue the wildlife of the Restless Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66108] = { id = 66108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sledgehammer of a Solution", description = "While I'm glad Tharu now sees my point of view, I'm also grateful he had you rescue wildlife while I was dawdling.\n\nThe situation is much more dire than anticipated; he was right to take action. With what we've learned, I fear this elemental bombardment won't stop until we've dealt with the gorlocs.\n\nIf I were Tharu and thinking actionably, I would go straight for their leaders. Without anyone to rally around, the fighting should dissipate and no longer threaten the wetlands.", progress = "This should buy us some room to breathe while we clean up this mess.", completion = "That ought to leave them scrambling--at least for a while.\n\nThank you for all your help, {name}.", objectives = "Slay Sogglmoggl, King of the Soggymaw and Whirglgurgl, King of the Windyfin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66110] = { id = 66110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Peace a Chance", completion = "<Captain Garrick salutes your approach.>\n\nWarlord Breka proves her honor once again by sending you to me.", objectives = "Introduce yourself to the Alliance representatives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66111] = { id = 66111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Elementals", completion = "For the Dragonscale Expedition!\n\n<Captain Garrick salutes you.>", objectives = "Kill 15 primal elementals in Wingrest Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66112] = { id = 66112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Always Be Crafting", description = "Have ye ever seen such powerful elementals?!\n\n<Grun cheers.>\n\nI hear the guards grumblin' 'bout havin' to fight 'em all the time, but they're missin' the big picture... Bigger elementals means bigger craftin' components!\n\nWhile you're out there clearin' the elementals for our safety or whate'er it is ye be doin', be sure to pick up pieces of the biggest ones ye can find. I want tae try makin' somethin' out of 'em!", progress = "I'm gonna build a grand helmet first... No, a hammer... No, a BIG hammer!", completion = "<Grun's eyes open wide as you hand him the primal cores.>\n\nIncredible! This is the best day of me life!", objectives = "Collect a Primal Molten Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66113] = { id = 66113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Inconspicuous Conveyance", objectives = "Repair the Borrowed Wagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66114] = { id = 66114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Benefit of the Queen", description = "We safeguard our precious eggs to protect the future of all dragonflights. The Primalists do not simply threaten pain or anguish with their actions. \n\nThey threaten us with extinction.\n\nI must inform our queen at once.", completion = "This is dire... but our flight has suffered many tragedies over the years. We shall endure.", objectives = "Ride with Majordomo Selistra to the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66115] = { id = 66115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mandate of the Red", description = "Our calling is care and compassion. We aid the other flights not only for their own sake, but for the sake of dragonkind as a whole.\n\nPerhaps speaking with the dragonspawn here at the Ruby Lifeshrine will help you understand us further.", progress = "The red dragonflight preserves the future of us all.", completion = "I hope you have grown to appreciate what we do.", objectives = "Talk to the tenders at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66116] = { id = 66116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Primary Threat", description = "There are far too many vulnerable eggs to secure. If the enemy breaks through, all is lost!\n\nI am sure our guards are mustering on the field to push them back. Speak to Commander Lethanak, and he will use your strength where it will be most helpful.", progress = "I need all the help I can get.", completion = "I will use every weapon in my arsenal to stop these foes.", objectives = "Find Commander Lethanak at the Flashfrost Assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66117] = { id = 66117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Battlefield" }
quests[66118] = { id = 66118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basalt Assault", description = "Raszageth and her Primalists have summoned towering earth elementals to break our walls. They must be stopped!", progress = "They will do anything they can to destroy our walls!", completion = "The Lifeshrine stands strong.", objectives = "Destroy 4 Enraged Cliffs in the Flashfrost Assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66119] = { id = 66119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby Life Pools: Primalist Invasion", description = "The Primalists have torn their way into our home. We were not prepared for such an intense attack... several got through.\n\nOne of our drakonid ventured in to follow them, but he has not reported his findings. I fear the worst.\n\nI will stand guard. No more shall breach our walls while we draw breath, but you must stop those who made it inside.\n\nGo!", progress = "They will destroy our future if we cannot stop them.", completion = "Our home will bear the wounds of this assault for years, but we are strong. We will endure... and the eggs we saved will bring about a bright future for us all.\n\nThank you.", objectives = "Enter the Ruby Life Pools and stop the Primalist attack.\n\nYou can enter the Ruby Life Pools solo by queuing for it in Follower Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66121] = { id = 66121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Evac", completion = "Nearly done.", objectives = "Rescue 4 eggs from the Flashfrost Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66122] = { id = 66122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proto-Fight", progress = "They intend to harm our dragons. They deserve no mercy.", completion = "They may have been our kin, and perhaps we could have approached them as our brethren... but their cruelty leaves no mercy in my heart.", objectives = "Defeat 3 proto-dragons in the Flashfrost Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66123] = { id = 66123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Off the Head", description = "Jadzigeth, one of Raszageth's foul lieutenants, proudly leads the Primalists here.\n\nLet us show them all what happens to those who stand against us.", progress = "There is no other path.", completion = "Our queen!", objectives = "Defeat Jadzigeth in the Frostflash Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66124] = { id = 66124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exeunt, Triumphant", description = "From what I saw, the queen fell back to the Wild Hatchery. It is an outpost to keep watch over the proto-drakes in the area... I only hope that its defenses are enough.\n\nWe must head there at once!", progress = "My queen...", completion = "I could not rest until the eggs were safe... this is a relief.\n\nThank you, {name}.", objectives = "Escape the Frostflash Enclave with Majordomo Selistra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66126] = { id = 66126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking Our Past", description = "Bring me an assembled Key", progress = "A restored Obsidian Key could allow us to unlock aspects of this forge that we have only dreamed about!", completion = "A wise choice. All these squabbles over the throne will not solidify our defenses. We must craft weapons and gear to fend off the djaradin.", objectives = "Collect 1 Assembled Key", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66128] = { id = 66128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next Steps", description = "These stones are an incredible discovery, even if their intended use is never realized.\n\nBut before we try them out, we have a process to adhere to. They must be examined and cataloged, and reports sent and received to both the Reliquary and Explorers' League headquarters.\n\nLet's meet back at basecamp. We can go over what's next.", progress = "Oh ye wouldn't believe the plans I have to get into that facility!", completion = "Don't ye worry. Show a little patience, and we'll get to the bottom a' this yet.", objectives = "Meet with Toddy and Naleidea in the Explorer's tent at the Dragonscale Basecamp in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66129] = { id = 66129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking Our Past", description = "Bring me an assembled Key", progress = "We must have the lost Obsidian Keys. The power they unlock is necessary to drive back the unbelievers.", completion = "This contribution shall ensure your place among Deathwing's chosen few. Together we shall sweep across the world and announce the Hour of Twilight!", objectives = "Collect 1 Assembled Key", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66130] = { id = 66130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking Our Past", description = "Bring me an assembled Key", progress = "Find me more restored Obsidian keys, and we shall unlock the full potential of the Obsidian Citadel.", completion = "Good work, champion. This key will allow us to access more of the Citadel's lost secrets.", objectives = "Collect 1 Assembled Key", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66131] = { id = 66131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking Our Past", description = "Bring me an assembled Key", progress = "Bring me additional restored keys, and we shall continue our work here.", completion = "Thank you, {name}. Your support in this matter shall bolster my claim to the throne.", objectives = "Collect 1 Assembled Key", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66133] = { id = 66133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys of Loyalty", objectives = "Collect 1 Greater Obsidian Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66134] = { id = 66134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth Pest Control", description = "You there! Hatchling!\n\nLend me a hand, won't you? These podlings are ripping up all my plants!\n\nAll kinds of elementals have invaded the gardens, and they seem to be... affecting the wildlife. It's like their energy has driven these podlings mad! More mad than usual!\n\nI've got my hands full with just these three. Please! Before they rip up all my flower beds.", progress = "I'm too old to be fighting podlings!", completion = "Thank the Titans you showed up! Otherwise I don't know if I'd ever get these pests to leave.\n\nSo what do you say to helping an old Drakonid out with the rest of the gardens?", objectives = "Kill 8 Agitated Seedlings in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66135] = { id = 66135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gardener's Apprentice", description = "Basilton! Lord Basilton, where are you?\n\nMy executive assistant and apprentice, Lord Basilton, has gone missing! He loves to explore, but he's even worse at defending himself than I am. I'm a gardener, not a warrior!\n\nCould you please go find that layabout? I need him here so I can think. He's usually in the shed, digging through piles of junk.\n\nBe careful though. He can be a bit prickly at first.", progress = "At my age, an executive assistant is a necessity.", completion = "Ah, there he is! My lovely assistant. Who's a good boy? A good, spiky boy? Basilton! Who's the spikiest? That's right! You are!\n\nAhem. Thank you, {name}.", objectives = "Search for Lord Basilton in the Garden Shed by cleaning up Piles of Junk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66136] = { id = 66136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Extract", description = "A huge fire elemental destroyed the pond a few days ago. I think it's behind all this ruckus, but it's too big to fight. We need to weaken it somehow.\n\nBut don't count Old Gryrmpech out just yet, I have a plan!\n\nWater elementals decided to make themselves at home in the Blue flight's gazebo. If you can collect enough essence from them, we might be able to use their magic against them.\n\nFight fire with fire, right? Well, fight fire with water, I guess.\n\nAnyway, you should probably get going.", progress = "In all my years, I've never seen so many elementals in one place. So why did it have to be my gardens?", completion = "Excellent! This is just what we need to snuff out those fire elementals once and for all.", objectives = "Collect 5 Watery Essence in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66137] = { id = 66137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lashing Out", description = "I'm sure the podlings aren't the only wildlife acting like hooligans.\n\nAlexstrasza's tree has always been a thorn in my side. Her life magic draws all sorts of plants and animals to it, good and bad. And guess who has to take care of the bad ones? Old Gryrmpech, that's who!\n\nAspects above, I'm getting too old for this.\n\nThe stewards aren't trained in combat, so it is up to you to take care of the Life-Binder's weed problem.", completion = "The elemental problem is more dire than I thought, if you killed that many. Alexstrasza will be happy, at least.", objectives = "Kill 10 Invasive Deathblossoms and Lasher Weedlings in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66138] = { id = 66138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Sands Through the Hourglass", description = "Like the rest of the gardens, Nozdormu's hourglass has had to weather the elemental unrest. Turbulent wind elementals came through and scattered the magical sand contained within.\n\nWithout this sand, Nozdormu's influence here is greatly diminished.\n\nAs a steward-in-training, I have been tasked with overseeing the hourglass at all times. If you would collect the sand in my stead, I would be eternally grateful.", progress = "I can rest easy knowing Nozdormu has already foreseen your success.", completion = "Excellent work.  Nozdormu informed me yesterday that he wishes to express his gratitude.", objectives = "Collect 8 Piles of Windswept Time Sand in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66139] = { id = 66139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame at Last", description = "Alright, youngling, I've placed all the water elemental essences in this jar for you.\n\nIf you just toss it at the big one, it should work. I mean, when has water not worked against fire? It's foolproof.\n\nThe heat, uh, isn't good for my joints, so I'll just stay here. I trust you can handle it.\n \nGood luck, young one!", progress = "You remind me of myself, when I was your age. Nothing could stand in the way of Gryrmpech!", completion = "Incredible! I wasn't sure it was going to work, but I'm glad it did.", objectives = "Use the Concentrated Essence of Water to defeat the Blazing Inferno in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66141] = { id = 66141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Traditions, Broken Bodies", description = "My fellow furbolg are no longer themselves. They have done... bad things. Now, they have become worse things.\n\nFurbolg has never fought furbolg!\n\nMy brother and I escaped them. I came here looking for help. He remains by our clan's den.\n\nHelp us before our clan is lost!", completion = "My brother spoke the truth.\n\nIt is even worse than when I left.", objectives = "Meet Garz and Narn on the way to Rustpine Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66147] = { id = 66147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals in the Water", description = "We might not look it this moment, but we are professionals. The Expedition entrusted us with finding a clutch of rare crystals in the area--a geological survey if you will.\n\nI'm still collecting myself after the gorloc attack. Would you be a dear and go look for these crystals? Bring samples back if you can.", progress = "Fieldwork is exhausting.", completion = "Excellent work! I'll get this to LOU-C and see what her little contraption can make of it.", objectives = "Collect 4 Crystal Samples in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66148] = { id = 66148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Former Furbolg Family", description = "Primalists came. They offered us new strength: the command of the elements.\n\nI did not think Stoneheart would accept their gifts. Our clan did not need power. He thought nothing of the cost.\n\nHis terrible decision cannot be unmade. The magic has corrupted my clan--like disease rots a root.\n\nMy heart breaks, but culling the corrupted is the only way.", progress = "It must be done.", completion = "I am sorry you met the Rustpine clan now. This is not my people.", objectives = "Kill 15 Rustpine furbolg and elementals, then meet Narn further in Rustpine Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66149] = { id = 66149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Influence", description = "Narn says not all the Rustpines followed Stoneheart or the Primalists.\n\nSome resisters are held against their will. Totems spewing rock and mud restrain them... to force them to obey. \n\nShatter the totems. Set them free!", progress = "My friends do not deserve this fate.", completion = "I will never forgive the Primalists for making our clan suffer.", objectives = "Destroy 3 Primalist Earthbind Totems, then meet Narn further in Rustpine Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66150] = { id = 66150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing Radza", description = "Radza Thunderclaw is our Spiritkeeper. She holds true our traditions and history.\n\nPrimalist beliefs go against everything our clan holds true. I knew she would defy Stoneheart! \n\nStoneheart will do anything to bring her to heel. No one is chieftain without Radza's blessing!\n\nNarn says Khargall Fivefangs, the Chieftain's guard, is trying to break her. If Radza dies, our clan dies with her.\n\nGo aid her, {name}, and be ready. He will not let her go without a fight.", completion = "So many of my clan have fallen in battle with their brothers and sisters... all for the promise of power.\n\n<Radza utters a guttural growl which fades into a long, mournful whisper.>", objectives = "Rescue Radza Thunderclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66151] = { id = 66151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Stone Heart", description = "We howl with grief for our chieftain, yet he lives.\n\nWhat remains of Stoneheart is in the cave ahead. Many tried to reason with him. \n\nHe killed them--and almost killed Narn.\n\nHe is a monster! This is the goal of the primalists. They would turn us into stone and flame to serve them.\n\nThere is no Rustpine left in him. He must be destroyed before others meet the same fate.", progress = "Our chieftain wanted power to protect the clan... but it took everything from us.", completion = "My chieftain, I am sorry.\n\nThere was nothing else that could be done.", objectives = "Kill Stoneheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66152] = { id = 66152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Go", description = "We cannot stay here.\n\nI do not know what to do... where to go next...\n\nWe will return to your Camp Nowhere. The tuskarr should know what happened at Rustpine.\n\nIf we tell our story and keep it, maybe it will not happen again...", completion = "Our clan has been clawed to shreds.\n\nI hope another will accept us.", objectives = "Meet Garz at Camp Nowhere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66154] = { id = 66154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salivatory Samples", description = "<The gaunt undead pinches the bridge of his nose and sighs heavily.>\n\nThis is going to reflect very poorly on my record. Somehow in a single day we've managed to stir up the local gorlocs, lose half of our equipment, and are now down a dwarf. \n\nIn this situation, protocol dictates that we be as efficient as possible. Go thin out some of our toothy antagonists and bring me their saliva for further testing while you're at it.\n\nOnly the good stuff, mind you.", progress = "Have you secured the samples?", completion = "Well, what do you know? Someone around here actually accomplished something. What's that old saying? Two for you, one for me?\n\n<Rowe takes a small sip from the beaker.>\n\nAh, that's the stuff.", objectives = "Collect 12 Saliva Samples in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66155] = { id = 66155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruriq's River Rapids Ride", description = "I did not expect my brother's approval... but it is welcome, all the same. \n\nThe time has come! Let's see if our hard work has paid off!\n\nJoin me in The Fallstrider, {name}, and we shall take off down the river, catching fish for Iskaara as we go!", progress = "With all of our hard work together, I'm certain our trip will be successful.", completion = "Phew, what a ride! It's a miracle the boat is in one piece!\n\nThank you very much, {name}. Let us meet again for another ride!", objectives = "Ride the Fallstrider down the river.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66156] = { id = 66156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Dragonscale Expedition", description = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer!\n\nReturn to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", completion = "Your deeds bring renown to all explorers. Take these supplies to aid you!", objectives = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66159] = { id = 66159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message Most Dire", description = "Kalecgos would not speak of what happened in the Azure Span till you arrived.\n\nWhatever he has to share gives me a terrible sense of foreboding, {name}.", completion = "Raszageth! She is attempting to find them... This is profoundly disturbing news.\n\nWe do not know where her Primalists will be next. Our city must be protected from her chaos.", objectives = "Speak with Alexstrasza at the Seat of the Aspects within Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66163] = { id = 66163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Hide", description = "Welcome to Valdrakken, {race}. \nThe climate in the city has been a bit warm of late, and I do not mean the weather.\n\nThe Primalists are skulking about, fomenting dissent among the citizens of our city.\n\nOur foes are crafty. They have been disguising themselves as citizens of our city to hide from the Scalesworn. They know how to avoid my guards but will not suspect an outsider.\n\nTake this Dragon's Eye gem, it should help you see through their disguises.\n\nGo reveal and kill these infiltrators!", progress = "Have you taken care of our infiltrator problem?", completion = "Good. Let this serve as a notice that the Primalists will never be welcome in Valdrakken!", objectives = "Kill 6 Primalist Infiltrators within Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66164] = { id = 66164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishy Fingers", description = "Now that Mordigan's off licking rocks, we can get to the crux of the problem...\n\nThose perfidious fishmen have pilfered my parts!\n\nWe weren't in this dinky little village for more than an hour and WHAM! Gorloc were swarming all over us! Rowe was yelling, Aelnara was screaming, and I'm flailing around with my wrench like a madgnome! \n\nSee if you can't salvage the situation and get some of my parts back!", progress = "This is sub-optimal.", completion = "You're back! I'll start getting the Geoscanner 289-07 reconfigured and as functional as circumstances allow. These seaside conditions are admittedly less than ideal.", objectives = "Recover 5 Stolen Parts in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66166] = { id = 66166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes and Ears", description = "The Primalists have been spewing their propaganda among the citizens of Valdrakken. \n\nOur enemies are too wily to say anything in the presence of my Scalesworn, but perhaps you might be able to get close enough to eavesdrop on their conversations.\n\nI have marked locations on your map for further investigation.\n\nYou may want to visit the Transmogrifier to see about changing your look to avoid any suspicion.\n\nTake this enchanted stone, as long as you have it on hand we will be able to communicate.", progress = "Well, find anything useful?", completion = "So, the Primalists are up to something in the south and soldiers have not been arriving from South Hold Garrison... This does not sound good {name}. That does not sound good at all.", objectives = "Locate Clues within Valdrakken, and visit the Transmogrifier to learn how to change your appearance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66167] = { id = 66167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southern Exposure", description = "Based on your discoveries I suspect the Primalists are attacking Commander Eranog's Garrison at South Hold. But, my Scalesworn cannot leave the city as that would be exactly what the Primalists are hoping for.\n\nI need your help again, {name}. \n\nTravel to South Hold, see what kind of forces we are facing, and if possible make contact with the garrison guardians there.", completion = "You have my thanks, and my apologies, stranger. In the heat of battle it is difficult to distinguish a friend from a foe, and there are plenty of foes around.", objectives = "Travel to South Hold Gate in search of making contact with the garrison guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66169] = { id = 66169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance, Served Hot", description = "The Primalists caught us completely unawares.\n\n<Velomir spits in disgust.>\n\nMy fellow guardians were ripped apart by these monsters. I would have joined them in death if you had not shown up when you did.\n\nOff in the distance I can still hear the sounds of battle. Perhaps others still live, maybe even Commander Eranog.\n\nLend me your aid. I need you to cause a distraction so I can sneak to a position closer in.\n\nKilling a few of these so called \"Magmasworn\" would be perfect.", progress = "Do you have a bodycount for me, {name}?", completion = "Great work, {class}. Those monsters deserve every bit of pain you gave them twice over!", objectives = "Kill 12 Magmasworn Primalists within South Hold Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66170] = { id = 66170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silent Vigil", description = "<Dori'thur hovers silently, peering at you with keen, expectant eyes.\n\nPerhaps the noble owl wishes you to see something of import.>", progress = "<Dori'thur ponders your actions.>", completion = "<Dori'thur blinks knowingly.>", objectives = "Witness Dori'thur's vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66173] = { id = 66173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hall of Samples", description = "Did you hear what that console said?\n\nThere's a hall full of samples. Ancient titan machinery? Specimens from other worlds? Only Tyr knows what's in there!\n\nLet's change that.", progress = "Do ye wonder what else the titans captured as \"samples?\"", completion = "If ye decide to retire from adventuring, I'm sure ye could find work as a dragon wrangler.", objectives = "Explore the Hall of Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66174] = { id = 66174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hall of the Aspects", description = "The Hall of the Aspects, eh? Why would Tyr seal something like this away? Was he hidin' something?\n\nThe implications are staggering--hopefully we'll find some answers in there.", progress = "Let's pop through that transporter before Naleidea gets cold feet!", completion = "I don't care what Naleidea says, I knew ye were the right choice from the beginning.", objectives = "Explore the Hall of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66175] = { id = 66175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Experiment", description = "Thanks to you, our geological survey is now operating at nearly 96% efficiency! \n\n<LOU-C furrows her eyebrows.>\n\nThose are rookie numbers.\n\nHelp me run the samples you collected through my Geoscanner 289-07. It should give us a baseline as to what exactly is going on at the plateau.", progress = "For science!", completion = "They say to expect the unexpected, but wow... this is unprecedented!", objectives = "Help LOU-C run her tests in Whaler's Nook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66176] = { id = 66176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Experimentation", description = "Go conduct experiments on the water elementals harassing the gorlocs!", objectives = "Conduct 6 elemental experiments in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66177] = { id = 66177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Dwarf Left Behind", description = "The salt levels here are off the charts! We need to find Mordigan and get him out of there. He must be dangerously dehydrated by now. \n\nHe's only been gone a couple hours. See if you can't determine which path the grumpy old dwarf took!", completion = "You've been busy. So have I.", objectives = "Follow Mordigan Ironjaw's path through Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66178] = { id = 66178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Day in the Groves", description = "Rymek was sent here by the blue flight to learn about and protect our gardens. \n\nI am glad for their support. We are few in number, and our losses have been great. The blue dragonflight commands powerful magic, so we can learn a great deal from each other.\n\nCome. Let us demonstrate the green dragonflight's important role here in the Dragon Isles.", completion = "It is so peaceful here.\n\nThis is Somnikus's favorite place to rest, but... he has been morose since his son was killed in the centaur attacks. \n\nBut we shall focus on the present. Let us show Rymek our purpose here in the groves.", objectives = "Meet Merithra and Rymek at the Leafy Repose in the Emerald Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66179] = { id = 66179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds for the Future", description = "The Primalists' attack left its mark on the Emerald Gardens. I wish to see it grow and flower once again.\n\nIn this part of the garden, we have an overabundance of lashers. Their seeds can be used by the Sisters of the Garden to cultivate vegetation in those damaged glades.\n\nThin out the lashers to collect their seeds, and then give those seeds to the Sisters. They sometimes struggle to inflict harm on any creature, even when it is in the best interest of the gardens overall.", progress = "Have you collected the seeds?", completion = "Thank you. Do not fear, the lashers always grow back at a remarkable rate. Their numbers will rebound quickly.", objectives = "Collect seeds from various Lashers and give them to Sisters of the Garden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66180] = { id = 66180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake the Ancients", description = "There are many ways to keep the gardens safe, and we have allies to help us.\n\nA few Ancients rest dormant in these glades. They are giant trees sworn to defend the forest and the creatures within. \n\nUse this fragment of my breath to wake them.", completion = "One of the ancients was slain? By frost?\n\nThis does not bode well. We must be alert. The Primalists could be preparing another assault on the garden.", objectives = "Use Merithra's Borrowed Breath to wake Ancient Guardians in the Emerald Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66181] = { id = 66181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frenzied Defender", description = "I have noticed that these gardens have rather diverse defenses, from the dragons to the drakonid and ancients... and even the wildlife!\n\nBut there is one defender that seems to have become rather too zealous in its protectiveness. It even tried to swoop at me when I arrived!\n\nAnd since we know something has been killing within these groves, it cannot hurt to be too cautious.\n\nUnfortunately, this creature must be slain before it can do more damage.", progress = "Have you found and put down that overzealous bird?", completion = "The gardens are more peaceful already, are they not?\n\nYou are quite capable, {race}.", objectives = "Slay the Frenzied Grovetalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66182] = { id = 66182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerithus's Research", description = "The green dragonflight has many duties, not solely in the tending of the garden. We also defend the Emerald Dream, and some extend their attention even further.\n\nMy son Gerithus, for example, has always had interest in all kinds of magic.\n\nYou and Rymek should seek him out, to see what he is working on and help where you can.", completion = "Welcome! I appreciate that my mother has been interested in my research. Even if it's a little far-fetched.\n\nThough I'm sure Rymek, as an emissary of the blue flight, will have a much greater understanding of magic than I do. I hope that we can make some real progress.\n\nLet's begin!", objectives = "Meet Gerithus deeper in the Emerald Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66183] = { id = 66183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Tears", description = "We may've only recently returned to the Emerald Gardens, relatively speaking, but we carry our long-lasting feelings with us.\n\nMany of us are still reeling from the death of Ysera, my grandmother. Including myself. I wish I had gotten to spend more time with her and to learn more from her. What amazing things she's seen in her life!\n\nIn places like the Emerald Gardens, when we shed tears, they can crystalize and carry great power within them. I have an idea for how this galvanized grief could help us.", progress = "Have you collected some of the Emerald Tears in the garden?", completion = "These are beautiful examples, {name}. Now let's see what we can do!", objectives = "Collect 8 Emerald Tears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66184] = { id = 66184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchors to Life", description = "Based on my research, I believe there's a way to reestablish Ysera's ties to the Emerald Dream, so we can bring her closer to Azeroth.\n\nWhen Ysera died, the Winter Queen used her own power to restore her in Ardenweald. For now, she's bound there, but I think if we can just get Ysera over into the Emerald Dream, we can use these anchors to keep her there.\n\nBut I'm getting ahead of everything.\n\nFirst, we have to infuse these anchors with the power of those Emerald Tears.", progress = "There is so much potential within ourselves.", completion = "That's it! I can feel the power in the anchors.\n\nNow, of course, there's just the one tiny problem of how to get Ysera to cross from the realms of death into the realms of life. One thing at a time.\n\nFor now, I'll get these anchors to the Shady Sanctuary for safekeeping.\n\nMy mother is here. She must have more that she wants you and Rymek to see.", objectives = "Empower the Inert Anchors with the Emerald Tears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66185] = { id = 66185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Weald", description = "It is time. I know I said that I was fine, but ever since Solethus' death, it's like I've been missing something essential.\n\nI am alive, and he is not. That feels... wrong.\n\nBut there might be a way I can set things right. Ysera is the only one who can help us get control of Ancient Bough again. I think I can help bring her back.\n\nIt's getting harder and harder to cross over. We need to make this count.\n\nTyrande and Malfurion will meet us there.", completion = "Greetings. Somnikus has told me of the grave threat in the Emerald Gardens. He has told me of his own part in it.\n\nBut I'm afraid the solution will not be as simple as he hopes.", objectives = "Meet Somnikus at the Grove of Awakening in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66186] = { id = 66186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price", description = "I am eager to return to the Emerald Dream and defend the gardens from the Incarnates and their followers. But I cannot leave Ardenweald yet, not with my bond to the Winter Queen.\n\nI dare not ask anyone to do this, unless they accept the consequences. As I did.\n\nBut there is one who could take my place.", completion = "It is settled. I will remain in Ardenweald.\n\nI remain to protect the Dream and all the hope that grows within it. It must be me.", objectives = "Witness the decision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66187] = { id = 66187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mad Mordigan & The Crystal King", description = "I've scouted the perimeter. If Mordigan's anywhere, he's inside this cave.\n\n<Muffled curses and insults echo out from the cave entrance.>\n\nHe's definitely inside this cave.\n\nLOU-C said these crystals have dangerous dehydrating properties. See if you can't separate him from his... geological finds. And try not to hurt him too much.\n\nHe's fairly respected in his field.", completion = "An inelegant solution, but I appreciate your quick thinking and... resourcefulness.", objectives = "Decrystallize Mordigan Ironjaw in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66188] = { id = 66188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's Rest", description = "Let us go into the Grove of Awakening. The Winter Queen is the only one who can transfer this bond from Ysera to me. I have faith that she will agree. She aided Ysera in a time of desperate need, and now Ysera can help us in turn.\n\nIf the Winter Queen agrees, I expect that I will not be able to remain awake for long. The weight of the bond will be heavy to bear.\n\nIn time, I hope that I may wake again and gaze upon the fully grown might of the new tree.", progress = "I long to see the twisting green expanse of the Dream once again.", completion = "It has been done. Malfurion will sleep here in my stead. And Tyrande will watch over her people as she has capably done for millennia before.\n\nNow, we must ready ourselves. When I cross over into the Emerald Dream, there will be a brief window when you can join me.\n\nAre you ready?", objectives = "Activate the Globes of Rebirth in the Grove of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66189] = { id = 66189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into the Life", description = "We mustn't delay. I can feel the energies of rebirth surging in me. I am ready to cross back into the Emerald Dream. \n\nFrom the realms of Death into Life.\n\nFollow me through the gate of Awakening, and we will race across the Dreamway to Ancient Bough. I expect there will be some resistance within, so be on your guard.", completion = "It is worse than I feared. I can destroy the ice that surrounds the grove, but there are too many enemies upon us. And we need to find a way to bring down the barrier that keeps the others out.\n\nWe must work quickly and vanquish these foes, so Merithra and the others can reinforce us.", objectives = "Fight your way across the Emerald Dreamway with Ysera and enter Ancient Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66190] = { id = 66190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Close", description = "I must take a moment to thank you, {name}, for all your help. \n\nTruly, I never thought I would have a chance to admire the Dream within Ancient Bough! Not as a humble emissary! How very kind.\n\nLord Somnikus has graciously invited me to set foot inside the grove and see the portal. I would be honored if you would join me.\n\nI will remember this moment for the rest of my life. Share it with me.", completion = "I... can't believe...\n\nThis cannot be...\n\nI failed. I trusted Rymek and his dragonkin, and they betrayed us all.", objectives = "Enter the Dream portal grove with Rymek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66191] = { id = 66191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Yet So Far", description = "I cannot slip into the Dream here as I once did. With the bough defenses activated, we are essentially blocked from the grove.\n\nBut I'm afraid it only gets worse, {name}.\n\nI believe Rymek did not merely trick us to gain access to the Dream. I suspect he is looking for something within it... something precious and powerful that I swore to protect. \n\nNot even Gerithus or Somnikus knew of its existence, but now, my hand is forced. You must know the truth.", completion = "Our situation is dire. Rymek has left us few options.\n\nHe has forced our hand. Now we must make great sacrifices.\n\nThough we may not be able to enter the grove from this side, there is a way in... from beyond the realms of life.", objectives = "Speak to Merithra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66196] = { id = 66196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quack For Help", description = "<This duckling flails around frantically inside the bubble, quacking in fright.>\n\n<Maybe the ecologists would know how to help it?>", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And {name} too of course.", completion = "We'll look after Waddles. Let us know if you find any other lost ducklings out there.", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66201] = { id = 66201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hooves of War", description = "Balakar will marshal his forces for war. I will do the same, but we are outnumbered.\n\nThe dragons have asked for our aid, and we can use their help to even the odds. To answer their call for an alliance, I must blow the Horn of Drusahl, but I need Ohn'ahra's blessing. Will you help me?\n\nGo to Teerakai and deliver my declaration of war to my lieutenant, Jebotai. He will marshal my forces and direct you to the mystics who can find Ohn'ahra.", progress = "What do you want, outsider?", completion = "<Jebotai reads the message. His face grows more and more concerned.>", objectives = "Deliver the Khanam Matra's message to Khansguard Jebotai at Teerakai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66203] = { id = 66203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wash Over Them" }
quests[66206] = { id = 66206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nozdormu, I've Come to Bargain" }
quests[66210] = { id = 66210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Family", description = "Your friend Kalecgos wishes to speak of ley lines, but preparations must be made for the funeral. \n\nWhile I meet with him, could you gather the final offerings from around Iskaara and place them in the funeral boat alongside dear old Ponoliak? \n\nI hope you take a moment to enjoy the town, as well! My people will welcome you warmly, especially after your help in Brackenhide.", progress = "Did you get yourself a bowl of soup?", completion = "Your friend is very inquisitive! Does he ever take a moment to relax?", objectives = "Collect 4 Funeral Offerings from around Iskaara, then place them in the funeral boat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66211] = { id = 66211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brackenhide Hollow: To the Source", description = "We cannot thank you enough for your aid pushing back the Brackenhide gnolls. \n\nBut they continue to gather, using their foul decay magic from some source deep within Brackenhide Hollow. Worse, we have not heard from the tuskarr in that area for weeks, now.\n\nI fear something terrible is happening there. We must protect our home. Please, gather your forces, find our people, and see what you can do about the decay!", progress = "We must save our people, and stop the spread of decay!", completion = "Iskaara would be lost without you.", objectives = "Enter Brackenhide Hollow and confront Decatriarch Wratheye.\n\nYou can access Brackenhide Hollow solo by queuing for it in Follower Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66212] = { id = 66212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing: Aileron Seamoth", description = "Doesn't ANYBODY know how to fish PROPERLY anymore?\n\n<Lukoturukk wiggles his nose angrily.>\n\nYou, with the face, go get me some fish. GOOD fish. And no grungles!", progress = "Well, what've you caught, then? \n\nIt better not be any skinny little ancheevies.", completion = "Hmmph.\n\nHmmmmmph.\n\n...you're alright.", objectives = "Fish up 5 Aileron Seamoths from the ocean around the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66213] = { id = 66213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weave of a Tale", description = "My dearest wife, Poa, is an excellent storyteller. \n\nBut it's been thirty years, and she tells the same ones over and over again! Please, {class}, talk to Poa and give her a new story to tell.\n\nWhat's that? Tell her a story about your adventures? Don't be ridiculous -- I don't want to hear about that! The greatest stories are always about fish. Tell a story about fish, even if you have to make one up!", progress = "I'm waiting...", completion = "Thank goodness, a new story. \n\nLet's hear it!", objectives = "Tell Elder Poa a fishy tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66217] = { id = 66217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Krojek the Shoreprowler", description = "We've been watching the great shark we know as Krojek for many years now, waiting for the best time to hunt him down. \n\nHis hunting ground has meandered closer and closer to the shore. That means the time is now. Gather your hunting party and take him out!", completion = "It is the cycle of the sea life out here. Some we leave to continue the line. Some we cull, some we eat. All in balance.", objectives = "Kill Krojek the Shoreprowler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66218] = { id = 66218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scampering Scamps", description = "Hello again.\n\nCould you do me and Norukk a favor? Our kids, Neelo and Nau, left to play. They know they should be back by now. \n\nI am occupied, so please find them. I doubt they are in danger; my kids know how to take care of themselves.", progress = "Neelo and Nau can fend for themselves. But they know they are supposed to be home helping by now.", completion = "Ta says all gnolls are dangerous and mean. But this is just a baby! \n\nMa says I always have to take care of Nau, and she's a baby, too.", objectives = "Find Neelo and Nau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66221] = { id = 66221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving On", description = "With the Bronze Oathstone restored, Alexstrasza can proceed with her plan.\n\nTravel to Valdrakken, {name}. She will want to hear of your success.", progress = "I thank you, {name}.", completion = "{name}, please accept our most sincere gratitude for all you have done for us. I will let you know when the time comes to accompany me on this next step.", objectives = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66222] = { id = 66222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calm Before the Storm", description = "The Nokhud are powerful and have many allies. It will take all we have to withstand them.\n\n{name}, you have the Khanam Matra's trust. Her orders were to rally our friends and prepare our people. \n\nI need your help. Seek Hojin to mobilize the remaining khansguard. Alert Scout Khenyug to possible Nokhud incursions. Inform Agura to expect wounded, and tell Gensai to prepare our provisions.\n\nAs for the mystics, I believe they left recently. I will see if any remain in Teerakai.", progress = "It is rare for us to meet outsiders. It is even more rare to have them helping us, as you are. Thank you.", completion = "I did not wish to cause a panic, but the people must be ready. Clan Nokhud is not known for mercy.", objectives = "Communicate Jebotai's orders to the townsfolk of Teerakai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66223] = { id = 66223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can We Keep It?", description = "He's only trying to eat us because he's so hungry! \n\nFish! Nobody can turn down some tasty, ice cold, raw fish!\n\nFrigidfish are the best, ever. You can fish them up all over the ocean! But if you can't fish one yourself, Jinkutuk in Iskaara will definitely sell you some. \n\nBring me so many he won't be hungry any more!", progress = "So many fishes! I want to eat them all!\n\n... But no. They're for Scaps. This is important.", completion = "Scaps is gonna love these and then we're gonna be the bestest of friends!", objectives = "Bring Neelo 7 Frigidfish from either a vendor in Iskaara or fishing in any Dragon Isles ocean water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66224] = { id = 66224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystic Mystery", description = "I'm sorry, I've failed to commune with Ohn'ahra. You will need someone else to fulfill the Khanam Matra's request.\n\nSeveral days ago, my fellow mystics were called to Ridgewater Retreat on an urgent request from Tigari Khan. They should still be there.\n\nMeet me outside of town. The least I can do is show you the way.", progress = "{name}, you're alright! Thank Ohn'ahra.\n\nOh! These are my totems.", completion = "I barely escaped that ambush with my life. I'm afraid my fellow mystics weren't so lucky....", objectives = "Meet up with Boku and travel to Ridgewater Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66225] = { id = 66225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toting Totems", description = "Boku asked why I sent a message calling all mystics to Ridgewater Retreat.\n\nI sent no such message. Balakar purposefully drew my mystics into a trap to cripple Clan Ohn'ir.\n\nBut there may be a second reason. The Nokhud are gathering mystic totems, as many as they can find. These totems are blessed by Ohn'ahra.\n\nThe Nokhud motives in this are unclear, but we cannot allow them to take Ohn'ahra's gifts. Recover as many totems as you can.", progress = "The totems are infused with Ohn'ahra's wind magic.\n\nYet the Nokhud have abandoned her teachings. What are they up to?", completion = "So many totems. So many fallen mystics.", objectives = "Gather 8 Bundles of Totems from the Nokhud at Ridgewater Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66226] = { id = 66226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emotional Support Companions", description = "Please don't hurt me... \n\nWhat? You're here to help? You must save the animals!\n\nThe Nokhud attacked without warning. We all fled for our lives! I barely escaped death by diving into the lake.\n\nThe animals! We left them behind. Please, I beg you, rescue the creatures. Who knows what cruelty the Nokhud have in store for them.", progress = "As initiates, we practice our healing arts by rehabilitating wounded creatures. \n\nFour creatures were under our care. However many you can rescue will be a relief.", completion = "You saved them! They're a bit worse for wear, but they're alive and will recover.\n\nThank you stranger. Please take this, as a token of our everlasting gratitude.", objectives = "Rescue the innocent creatures from the Nokhud at Ridgewater Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66227] = { id = 66227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Good Fishing", description = "Another pair of hands! I could use some help catching enough fish to bring home for a meal.\n\nThese Kirin Tor seem concerned about something called magical anomalies in the area, whatever that means.\n\nYou're all welcome to stay here as long as you pitch in and help out.\n\nGrab a fishing pole and start fishing. Many hands make light work!", progress = "Let me know if you need a few tips.", completion = "Ah, that will do nicely! Thank you, adventurer.", objectives = "Catch 3 blue-tailed minnows within Khuri's Fishing Spot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66228] = { id = 66228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Antonidas", description = "The Kirin Tor have our main camp set up to the south of here: Camp Antonidas.\n\nI believe Noriko and Khadgar are there now gathering adventurers to aid Kalecgos in reclaiming the Azure Oathstone.\n\nIf you wish to help in our endeavours, go there.", completion = "Ah, {name}. Good to see you...\n\nHold on... do you feel that?", objectives = "Meet Noriko the All-Remembering in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66230] = { id = 66230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sketchy Request", description = "The tarasek took everything they could get their claws on, including my scouting ledger.\n\nThese overgrown lizards hoard trinkets and trophies by the dozens. I am sure that they stashed my ledger away somewhere. Could you keep an eye out for it as you work your way through the pass?\n\nOh, and {name}? If you do manage to find it, please do not look inside. The contents are sort of... personal.", progress = "Did you find anything else, {name}?", completion = "Ah... You really did find it.\n\nIn truth, it's more of a sketchbook than a ledger. For as long as I can remember, I've been more interested in doodling than scouting...\n\n<Alvi looses a long, low sigh.>\n\nMaybe if I had actually done my job properly, then Nori wouldn't have gotten hurt.\n\nI have to fix this... but I don't know if I can do it alone.", objectives = "Retrieve Alvi's \"Ledger\" and return it to Waywatcher Alvi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66232] = { id = 66232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Afront 'Till A Salt", description = "We don't mind accommodating you and your friends in our little place--not that anyone asked-- but would you be a good neighbor and nab me some crystal flakes if you're going up to the springs? We use 'em to preserve all kinds of things. It's a crucial part of keeping food around here.\n\nThe larger gorlocs are absolutely covered in the stuff. Maybe get some flakes off them?", progress = "Now that you mention it, I'm actually pretty hungry.", completion = "This is will go a long way in helping us in these parts. We just might let your friends stick around...", objectives = "Gather 120 Crystal Flakes in Gorloc Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66236] = { id = 66236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching Wind", description = "The Nokhud are collecting totems. The Primalists are capturing ohuna. And Ohn'ahra is silent.\n\nWhatever the Nokhud plans are, we must foil them. You and Boku must travel to Windsong Rise. Our enemies are likely there already.\n\nSearch for Ohn'ahra there. If her children are in danger, she will undoubtedly go to them, and we must help. The Windmother is powerful, but I fear what these Primalists are capable of.", completion = "Balakar and these Primalists have trampled on our most sacred beliefs.", objectives = "Meet Boku at Windsong Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66237] = { id = 66237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Allies", description = "Our arrival will not have gone unnoticed.\n\nAllow me to speak with them before we enter. I have something of a history with the council.\n\nThere will be time for introductions after.", completion = "A warmer welcome than I feared.", objectives = "Speak with the authorities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66239] = { id = 66239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spreading Decay", description = "<Brena turns Kargpaw's totem over and over in her thick hands.>\n\nKargpaw is a pawn. He isn't the source of this rot. We must find it, before the decay spreads further.\n\nThe closest tuskarr presence from here is a trading outpost, just across the bridge on the way to Iskaara.\n\nWe should check in with them... and quickly.", completion = "As I feared, they were attacked as well.", objectives = "Meet Brena at the trading outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66241] = { id = 66241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thaldraszus Rally", description = "Fly through the checkpoint rings marking the course." }
quests[66242] = { id = 66242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weather Control", description = "This unnatural storm is heavy with magic. By the looks of it, the Nokhud are learning to manipulate the sacred essence of Windsong Rise to create storm elementals. Some have had more success than others...\n\n<Boku gestures to the unfortunate Nokhud initiate nearby still smoking from lightning burns.>\n\n{name}, we can't allow them to continue.", progress = "The Nokhud will regret abandoning Ohn'ahra for the Primalists!", completion = "I don't want to spill blood, but the Nokhud must be stopped.", objectives = "Kill 8 Stormbound Essences and 6 Stormcaller Initiates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66243] = { id = 66243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift of Hope", description = "Greetings, Maw Walker.\n\nI bear a summons from the Winter Queen. She requests your presence in Ardenweald to witness a ceremony involving others from your world.\n\nShandris Feathermoon will be among them. You can find her in the Grove of Awakening.", progress = "The Winter Queen awaits us, {name}.", completion = "The Winter Queen's gift... what we just witnessed...\n\n<Shandris's eyes glisten with tears of hope.>\n\nWe must ask Ysera to help us keep this precious seed safe.", objectives = "Meet Shandris Feathermoon in the Grove of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66244] = { id = 66244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Valdrakken", description = "Thanks to you, we narrowly avoided a complete catastrophe.\n\nHowever, we should convene with the other Aspects and share word of what happened here.\n\nPlease meet me at the Seat of the Aspects within Valdrakken. I'm sure the others will have insight into what Raszageth and her Primalists are attempting.\n\nThere is a crossing into Thaldraszus north and a bit east of here. The flight is scenic, but do not take too long getting there.", completion = "Welcome to Valdrakken, {name}. Kalecgos says there is news about the Azure Span.", objectives = "Travel to Valdrakken and meet with Alexstrasza the Life-Binder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66245] = { id = 66245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember the Fallen", description = "So many of my comrades have fallen.\n\nPlease... Collect their identifying signets so that their names may not be forgotten.", progress = "How goes your task, hero? Did you find any signets?", completion = "Their memories will be honored.", objectives = "Collect 8 South Hold Garrison Signets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66246] = { id = 66246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fog of Battle", description = "The Primalist attack came suddenly and with no warning. My unit attempted to find our leader, Commander Eranog, but before we could get to the other side of the garrison we were cut off.\n\nIn the battle my unit leader, Sergeant Tagrik, held off three Primalists by himself as Kaora, Mikor, and myself battled at his side.\n\nTheir screams are the last thing I remember before I fell. \n\nPlease, {race}, if you see any signs of my unit let me know what happened to them.", progress = "Have you found what happened to my unit? I fear the worst, but I have hope that they survived.", completion = "This... pains me to hear... but I understand. Thank you, {class}.", objectives = "Search for the members of Guardian Velomir's unit in the South Hold Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66247] = { id = 66247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slightly Used Weapons", description = "This spear appears to be in good shape, given the condition of its former owner.\n\nGuardian Velomir mentioned to keep an eye out for useful materials, perhaps a few more of these spears can be obtained from the Magmasworn.", progress = "Find anything worthwhile out there?", completion = "Good find, {name}! These should be useful.", objectives = "Gather 6 Magmasworn Spears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66248] = { id = 66248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tying Things Together", description = "This coil of heavy rope seems to be in good condition. \n\nGuardian Velomir said to keep an eye out for useful materials, perhaps if you can find a few more coils he might find them useful.", progress = "What is it, friend? Did you find something?", completion = "What is this? Rope? There is no time to make a net!\n\nWait... I have an idea. There are some old weapons that we could use with these... \n\nGood eye, {name}! These are perfect!", objectives = "Gather 5 Coils of Heavy Rope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66249] = { id = 66249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Sky", description = "You did well to gather those spears and rope. With them, we can ensure those haughty Primalists will no longer rule the skies!\n\nThere is a platform up the stairway with several Siege Scorpions. If you use the rope to string their bows and use the spears as ammunition, you should be able to strike the Magmasworn's dragons in the air!\n\nOnce cleared, the path up the spire will be safe and we can continue our search for Commander Eranog.", completion = "Well done, {name}! That should take some heat off us. \n\nKeep your weapon in hand though, we are not done yet.", objectives = "Control a Siege Scorpion and then use it to clear the skies of Magmasworn Trueborn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66250] = { id = 66250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's The Chief?", description = "This is the only part of the fortress we haven't yet searched, {name}. If Commander Eranog is anywhere, it has to be here.\n\n<Velomir glances towards the nearby doorway.>\n\nLet us see what we can find out.", completion = "Damn it all! The commander was behind this? I cannot believe he would betray us like this.", objectives = "Accompany Guardian Velomir and inspect the Lookout Tower within South Hold Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66251] = { id = 66251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Fighter", description = "Commander Eranog has betrayed us and left this beast in charge.\n\nYou have done so much for me already, but I can not handle that monster in my current state.\n\nPlease, do this one last thing for me and help ensure that South Hold Gate does not fall to these Primalists.\n\nWe must kill their leader!\n\nHelp me, {name}.", completion = "With their leader dead these Primalists should be easy for reinforcements from Valdrakken to clear out.", objectives = "Kill Magmatalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66252] = { id = 66252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting In", description = "The Primalists threat has been diminished, {name}. Forces from Valdrakken will be headed in soon, and can clean up any remnants. \n\nYou should head back to the city and inform Captain Drine of what has happened. She will be interested to know what occurred here with Commander Eranog.\n\nThank you again, {name}, for everything.", completion = "Eranog joined the Primalists? Flame and Scale, this is a terrible development!\n\nHowever, you were able to prevent them from taking South Hold Gate.\n\nThat is no small feat. I appreciate your service to Valdrakken, {name}. It will not be forgotten.", objectives = "Return to Valdrakken and report to Captain Drine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66253] = { id = 66253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Shipments", description = "Tha shipments from Shiri and Zen'kala keep comin' in, we can barely keep up! But one of my workers thinks I won't notice if he shaves a little off the top. \n\nThe goblins here have been workin' on a little device to help make a mess of this thief: an exploding pie.\n\nLook for Kanyaku and throw one straight at him. I'm sure he's makin' mischief somewhere.", progress = "Throw an explosive pie at the thief to get the shipment.", completion = "Great work mon.", objectives = "Throw the explosive pie at the thief and retrieve 1 Shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66254] = { id = 66254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pessimistic Mystic", description = "War? Dragons? You need me to contact Ohn'ahra?\n\nI can't. I can't hear Ohn'ahra at all. I'm just an initiate, and it seems like Ohn'ahra has withdrawn her blessings from me. Maybe I'm not good enough...\n\n<Boku starts digging through a satchel.>\n\nWhen my mentor assigned me to this clan, she gifted me with these totems. She said they would empower me if ever I doubted myself.\n\nWill you help me place them? I will try to call upon Ohn'ahra one more time.", completion = "Still nothing. Not even a sigh from Ohn'ahra.", objectives = "Place the Empowerment Totems around Boku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66256] = { id = 66256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle-itarian", description = "We've discovered why the Nokhud want mystic totems. They can be used to capture the Children of Ohn'ahra. Though the Nokhud have stolen the totems, the Primalists are the ones behind this blasphemy.\n\nThe Children of Ohn'ahra are sacred ohuna, blessed by the Windmother herself. Please, {name}, free any ohuna you see! And if you come across any Primalists...\n\n<Boku trails off, but his expression is one of grim determination.>", progress = "The Children of Ohn'ahra bear the spirits of the honored dead to the beyond.", completion = "After all Ohn'ahra has done for us, we must do all we can to help her children. Thank you, {name}.", objectives = "Free 6 Children of Ohn'ahra and eliminate 6 Primalists at Windsong Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66257] = { id = 66257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fowl Sorcery", description = "It is said that Ohn'ahra infused the spear of our ancestor, Maruuk, with her power. Balakar Khan must have told the Primalists about that legend.\n\nThey have stolen the magic from Ohn'ahra's children, polluted it with storm sorcery, and infused it into ballista bolts. Why would the Nokhud need such weapons?\n\nWe shouldn't wait to find out. These storm bolts are being loaded into wagons for transport. Take my totems and place one atop each wagon you come across. My wind magic will smash them to pieces.", progress = "You might want to run after placing a totem.", completion = "I'm sure there's more out there, but we destroyed what we could. Hopefully, this will at least slow them down.", objectives = "Use Boku's Wind Totem to destroy the Nokhud wagons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66258] = { id = 66258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh No, Ohn'ahra!", description = "That Primalist is restraining Ohn'ahra, but just barely. She doesn't seem to notice us.\n\nTigari Khan would say, \"Even the slightest breeze can topple a teetering stone.\" If I can disrupt her spell, even just a little, Ohn'ahra might be able to break free.\n\nKeep the guards distracted. I have an idea.", completion = "We took quite a tumble. We're lucky to be alive.", objectives = "Defeat enemies as Boku tries to free Ohn'ahra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66259] = { id = 66259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Storm of Ill Tidings", description = "{name}, we need to tell the Khanam Matra everything that's happened, including the capture of Ohn'ahra.\n\nYou must go to Maruukai as quickly as you can. You'll have to go alone. I was hurt in the fall, and I'd just slow you down.\n\nDon't worry about me. I'll catch up later. Go!", progress = "Well? Speak.", completion = "This is dire news, {name}, but we cannot lose focus. We are bruised but not beaten.", objectives = "Deliver your report to the Khanam Matra in Maruukai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66261] = { id = 66261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Minor Setback", description = "Ah, adventurer! Just the sort of well-armed individual I was hoping to encounter.\n\nI'm here in this literal backwater on very important Kirin Tor business, you see, and whilst I was beginning to set up my camp, I was chased off by filthy, mangy gnolls.\n\nIn fact, a rather concerning number of gnolls have gathered nearby, enough that I believe they pose a threat to the wider Span.\n\nFear not though, for I have a plan! Meet me in the lake just over there, and I'll explain everything.", completion = "Now, to work!", objectives = "Reach Detry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66262] = { id = 66262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Water Cleanup", description = "First things first--I need my base of operations back! But the elementals running amok around here have made it very difficult to gain even a toehold.\n\nAnd of course it is those wretched gnolls' fault.\n\nThe gnolls have dumped so much refuse, offal, and Light knows what else into the lake that the local elementals have started to go berserk.\n\nBe a dear and clean up a few of the more revolting messes before things come to a head. And, more importantly, before they stain my robes permanently!", progress = "Ugh, the smell is horrific.", completion = "I can taste the difference already!", objectives = "Clean 6 Rotting Piles from the lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66263] = { id = 66263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Precision Approach", description = "Gnolls are awful creatures. Smelly. Always scratching, laughing at you. And there are multitudes here and more are constantly arriving. We, and by that I mean you, could reap them like wheat for days and never get anywhere. They can't be suffered to stay here.\n\nWe must strike at the heart of the snake! Remove their leadership and they'll be paralyzed with indecision and despair. \n\nWhat do you mean why are we doing this? Isn't it obvious? They're gnolls! What more reason could one need?", progress = "Did I mention I'm allergic to gnoll fur? My throat gets itchy just thinking about them.", completion = "How they must despair!", objectives = "Kill Flayfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66264] = { id = 66264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmed and Docile", description = "There's a frankly unnerving amount of weaponry being waved about up there. Relieving them of some should help calm things down. Or at least calm my nerves.\n\nWhat are they going to do without weapons, after all? Attack you with their bare hands? Ha!", progress = "Surely they're just lying about?", completion = "Oh, those? Just dump them anywhere. I'm sure the elementals won't mind.", objectives = "Acquire 15 Gnawbone Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66265] = { id = 66265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's Next?", description = "Aha! Well, it seems that another gnoll has stepped up to assume command. Just as I expected. Yes.\n\nHaving a trusted vice-warlord to ensure continuation of government makes perfect sense now, doesn't it? We'll just have to hit them a little harder to tumble their bureaucracy, hm?\n\nWhat? Am I going to take this moment to reflect on whether I'm rushing to judgement on these gnolls? Ridiculous! They're gnolls! \n\nQuickly now! Kill Cracktooth before the iron cools off or they arrange for an election!", completion = "Ha! Maybe next time they'll think twice before electing a new leader!", objectives = "Kill Cracktooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66266] = { id = 66266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Mongrels", description = "Those flea-bitten Hyena Mongrels the gnolls breed have got to go! Not only do they have no manners at all--you would not believe the places I've seen them relieve themselves--but they may very well be able to sniff me out despite my exemplary illusions.\n\nDo the well-mannered world a favor and remove them from it.", completion = "Play dead, indeed!", objectives = "Slay 3 Hyena Matriarchs and 12 Hyena Mongrels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66267] = { id = 66267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "M.E.T.A.", description = "Those fiends! Pillaging and murder are one thing, but animal abuse? I'll not stand for it. \n\nThe gnolls have set out traps for animals to catch and feed to their slavering hyena mutts. Find a way to free their fluffy captives and show the ruffians how a mage ethically treats animals!\n\nOf course this makes ethical sense in light of my recent actions. What exactly are you trying to insinuate?", completion = "That'll show those brutes!", objectives = "Free 6 abused animals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66268] = { id = 66268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Try's the Charm", description = "What? Another one's seized power? Whatever happened to abhorring a vacuum? Or at least waiting for a respectful period of mourning to pass in order to keep up appearances?\n\nDo they have no decency? No sense of propriety? No respect for a well-crafted plan? I made charts!\n\nDeal with this Bloodclaw fellow. I need a moment.\n\nAnd I don't need your nagging comments, thank you very much!", progress = "All according to plan!", completion = "Finally! That has to be the last one. Right?", objectives = "Kill Bloodclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66269] = { id = 66269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just To Be Sure", description = "Just... kill anyone who looks like they might be magically inclined. Or has organizational skills. Or looks overly ambitious.\n\nReally, just use your best judgement on this one.\n\nYour \"best judgement\" is to stop speaking to me? Come on, {class}! They're... up to something nefarious, obviously!", progress = "Don't they know they've been outwitted?", completion = "That had to work, right?", objectives = "Slay 12 Stormfang elementalists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66270] = { id = 66270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whack-a-Gnoll", description = "Oh, Light... there are more on their way! How could this happen?\n\nAll my careful planning! The days spent hiding in this rancid lake! The assassinations!\n\nThis should have thrown them into chaos and caused their settlement to crumble, but we've barely slowed them down!\n\nMaybe... maybe you're right, {name}. I've been wrong all along...\n\nNo! Impossible! We're in too deep now anyway.\n\nGo...deal with these new arrivals. I need time to collect myself.", progress = "What are you waiting for?", completion = "They're just going to keep fighting until they find a new leader? That settles it then. If I'm ever going to have a base of operations here, we'll have to kill all of them.\n\nThe plan is that we...\n\nWait, you're leaving? You don't want any part of this? What am I going to do? I can't leave this lake now that I've made an enemy of the gnolls!\n\nFine! Side with those flea-bitten miscreants!\n\nTake what I promised and go. You're not the only \"champion\" in these woods! I'll find someone else to help me!", objectives = "Defeat the would-be warlords.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66278] = { id = 66278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Drakonid's Junk", description = "<A glistening pocket watch lays amongst the many piles of junk. Maybe Gryrmpech will know what to do with it.>", completion = "This was in the shed? It's not mine, but I think I remember who it belongs to.", objectives = "Bring the pocket watch to Gryrmpech in the Gardens.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66279] = { id = 66279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Kid on the Clock", description = "Oh yeah, this pocket watch belongs to one of the stewards that help me tend to the gardens. \n\nHe's one of Nozdormu's. Orizmu, I think? I can't keep all these kids straight. Most days he stands next to that hourglass near Alexstraza's tree without moving. Or blinking.\n\nNozdormu's bunch have always been strange, if you ask me. But, he'll be grateful you brought this to him.", progress = "Walking all the way down to the sundial is too much effort for my old bones.", completion = "Thank you, {name}.  Nozdormu will be pleased to have this returned.", objectives = "Take the pocket watch to Orizmu in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66299] = { id = 66299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Awaited Egg-splosion", description = "Our prototype worked! Excellent!\n\nNow it's time for the main course. This time, YOU are the chef.\n\nWith some necessary adjustments, you'll suit up in your disguise again. Then you'll take our masterpiece EGG-splosive, dunk it in this rancid stew here, head up to the matriarch's cave, plate it for her, and glide back down with the blasts detonating behind you!\n\nIf all things go as planned, she'll be toast. Because of the explosion. Which will burn her to toasty bits.", progress = "Careful with that chef's hat. It's bound to be a collector's item one day!", completion = "Things didn't go exactly to plan, but no good Goblin scheme ever does! Nice work!\n\nThere will still be Screechflight here, but they'll be easier to cull without their Matriarch organizing their efforts. And the Bluefeathers will actually have a chance to survive.\n\nHarpies and dragons aren't that different. Forgetting their attempted mass digestion of the cliffside, they're akin to a civilization of their own. Maybe there's a peaceful brood out there? \n\nOh, and keep the disguise. Looks good on you.", objectives = "Slay the Screechflight Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66308] = { id = 66308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Fire", description = "The creation of new weapons and armor in the Earth-Warder's Forge will insure our eventual victory over the Djaradin.\n\nThe flames of the forge though must be constantly kept fueled. Cindershard Coal will provide the strongest heat, necessary to forge weapons.\n\nYou can find Cindershard Coal from deposits and Elementals within the Cindershard Seam.", progress = "Have you collected fresh Cindershard Coal?", completion = "This coal will do nicely, {name}. That should keep the forge going for a while longer.", objectives = "Collect 30 Cindershard Coal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66320] = { id = 66320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flow of Time", description = "The threads of time flow like a river, with many bends and branches. Occasionally, those flows can be changed. However, any anomaly left unresolved may doom our destiny to a false timeline.\n\nWe are quickly approaching one of those anomalies. I have sent Chronormu to the Shifting Sands to investigate and correct any issues to the one true timeline.\n\nI foresee that your assistance will be invaluable. \n\nPlease lend us your aid and meet with Chronormu.", completion = "Hello! ... again? I think?", objectives = "Travel to the Shifting Sands and speak with Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66321] = { id = 66321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Their Efforts", description = "Djaradin forces are threatening an attack on our position. I can feel it down to my claws. \n\nWe should strike first. Before they have a chance to mobilize!\n\nGo to the Burning Ascent and wreak havoc on the djaradin forces there.", progress = "Have you weakened the djaradin forces?", completion = "They won't forget the destruction you wrought for a while. Nicely done.", objectives = "Djaradin forces eliminated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66323] = { id = 66323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idling Pie", description = "Now that we have the wares back we can finish up here. But all my workers are lazin' about the city. \n\nFind where they're hidin' and 'encourage' 'em to head back here. A little leftover pie to the face, should have 'em runnin'.", completion = "Many thanks, everyone is back and workin' hard. <his eyes glance over to an extra pie>", objectives = "Wake up 3 workers in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66324] = { id = 66324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Forgotten", description = "The antidote is ready. Use it to search the Support Creche for survivors. Work quickly--the effect will not last long, so you may have to reapply it.\n\nIf any of my people yet draw breath, save them.\n\nAnd if they do not, I ask that you recover their horn signets so that their names may be honored.\n\nWhile inside, perhaps you can find evidence of how this infestation came to be.", progress = "None shall die or suffer if it is within my power to prevent it.", completion = "Thank you for rescuing those who could be saved.\n\nRethenash. Katrinasa. Tenezeth.\n\nI vow that the names of the fallen will be remembered.", objectives = "Recover items and survivors from within the Support Creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66326] = { id = 66326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tools of One's Trade", description = "A forge of this power needs specialized tools--ones that can take the tremendous heat. \n\nBut the djaradin have ransacked the place and stole many of the tools we need for this work.\n\nIf you can, recover those tools from them, so that we may continue our efforts to arm our allies.", progress = "Have you found the tools we require?", completion = "This is a good start. We can work with the tools you recovered for the time being.", objectives = "Collect 1 Precision Scale Hammer, 1 Obsidian Bickern, 5 Blacksteel Tongs, and 10 Dragonclaw Punches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66327] = { id = 66327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Wind", description = "We must take a moment to pause and consider our strategy. \n\nWe need Ohn'ahra's blessing to sound the Horn of Drusahl and summon the green dragons. Without their aid, we cannot win this war. The Nokhud already outnumber the other clans, and their forces are bolstered by the Primalists. And now Koroleth has captured our Windmother! We must therefore find Ohn'ahra before the Nokhud can launch their final attack and encircle Maruukai.\n\nI will send all of our scouts. I only hope we can find her in time.", progress = "We should depart as quickly as possible. You may ride Taivan and accompany us, or meet us at the Horn of Drusahl.", completion = "We are too late. The Nokhud have overrun the Horn of Drusahl and slaughtered my people. \n\nThis act of aggression will not go unanswered.", objectives = "Listen to Scout Tomul's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66328] = { id = 66328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Dragon Down", description = "Those dragons went down over the plains to the west. We must get to them quickly before the Nokhud do.\n\nWe would not want them to think of all Maruuk as their enemies because of Balakar's actions.", progress = "The dragons need our help, outsider. We should hurry!", completion = "Our ancestors said the green dragons were tempered and wise. We are fortunate they restrained their anger long enough to hear our side of the story.\n\nNow that we know the Primalists and Nokhud are our common enemy, it is time to take them down.", objectives = "Meet the Khanam Matra at the watering hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66329] = { id = 66329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blowing of the Horn", description = "Why would they have brought Ohn'ahra here? Unless... \n\n{name}! I do not think Balakar intends to destroy the Horn. I think this is a trap! We must find a way past this wind, quickly!", progress = "No, Balakar!", completion = "I will not rest until Balakar answers for the crimes he committed here today. The slaughter of my people, the blasphemy against Ohn'ahra, the treachery against our ancient ally....\n\nVengeance will have to wait. There are more pressing matters. We must help the green dragons.", objectives = "Witness Balakar and Koroleth's plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66331] = { id = 66331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Primalist Front", description = "The Khanam Matra sent word that she and her forces have arrived in the Emerald Gardens. They've located Koroleth and her Primalists. It appears a massive enemy invasion is gathering on a beach to the north.\n\nWisely, she has several scouts watching strategic locations around the battlefield. Go and collect their reports, then meet me and my forces at the battlefront. Glory awaits us in battle, and, if we succeed, there will be vengeance.", progress = "Every moment we delay, our enemies advance. We must move quickly, {name}.", completion = "Our enemies are one step ahead of us. Do not despair. Our resolve is as strong as our alliance. Prepare yourself, {name}.", objectives = "Speak to Scout Tomul, Ari and Belika, Ohn Seshteng, and Merithra in the Storm Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66333] = { id = 66333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for Solethus", description = "So long as a single green dragon draws breath, these Primalists will not defile the Ancient Bough without a fight.\n\nWe are eager to do our part in this battle, but as long as those dragonkiller ballistae are on the field, we cannot approach. The Nokhud's strongest warriors guard them, so you will need to take down the warriors as well.\n\nDestroy the ballistae and Nokhud Warmongers. Eliminate this threat, and the green dragons will turn the tide of battle.", progress = "Make haste, mortal. I will not commit dragons to battle while those ballistae remain.", completion = "Good riddance to those awful weapons. May no other dragon suffer as Solethus did.", objectives = "Kill 3 Nokhud Warmongers and destroy 3 Dragon-Killer Ballistae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66335] = { id = 66335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deconstruct Additional Pylons", description = "With those vile weapons destroyed, the green dragonflight can join the fray in force.\n\nWe are much more familiar with the situation on the ground. We need to light up some targets, so Merithra and her dragons can strike from above.\n\nMerithra gave me these enchanted seeds. Place them near the Primalist pylons. We will use their light to call in attacks from airborne dragons.", progress = "I would appreciate if you did not stand so close to me with those enchanted seeds. Thank you.", completion = "I will remain forever grateful that the dragons were on our side during this battle.", objectives = "Mark the Primalist Pylons with Enchanted Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66336] = { id = 66336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Isle of Emerald", description = "Your part in this has not escaped me, mortal. It is in large part due to your bravery that we were able to defeat the Primalists.\n\nI have invited the centaur to join me under the Ancient Bough. You, along with the Khanam Matra and her people, are welcome in our home.\n\nFollow this path through the archway across the water and into the trees beyond. I will wait for you there.", completion = "Welcome to the Ancient Bough. You stand before the Emerald Oathstone of the green dragonflight.", objectives = "Meet Merithra in the Ancient Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66337] = { id = 66337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormbreaker", description = "{name}, to me! We are within reach of victory!\n\nThe Primalist ranks are broken, and their war is all but through. Everything we have achieved hinges on this final battle against the Primalist leader, Koroleth.\n\nLet us finish this, you and I! Together! To battle, <brother/sister>!", completion = "At last, it is done. Our sacred isle is safe once again. Thank you for all you have done for my kind, {name}.", objectives = "Defeat Koroleth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66339] = { id = 66339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nokhud Offensive: The Wind Belongs to the Sky", description = "Is this the end of your time with us, {name}, or will you aid us once again?\n\nMy scouts report that Balakar has withdrawn into his stronghold, where he is holding Ohn'ahra. This is unacceptable!\n\nMeanwhile, his Nokhud raiders storm across the plains wreaking havoc. While we engage them in battle, you could infiltrate the Nokhud stronghold and rescue Ohn'ahra. Will you do this for us?", completion = "With this victory, you have helped the Maruuk more than you will ever know. Our most sincere thanks, {name}. Go with the blessings of Ohn'ahra.", objectives = "Defeat Balakar Khan and rescue Ohn'ahra in The Nokhud Offensive.\n\nYou can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66340] = { id = 66340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Azure", description = "We have done our part. Though I must remain here to watch over the Oathstone and guide the green dragonflight, know that you leave here with our gratitude and faith.\n\nI have received word the Kirin Tor are seeking help in claiming the Azure Oathstone. Helping them with their Oathstone will bring us one step closer to healing Azeroth.\n\nFind Pakina and Masud the Wise of the Kirin Tor. They will instruct you further. Safe journey and pleasant dreams, {name}.", completion = "Hail adventurer! I'm glad our call for help reached you.", objectives = "Meet Masud the Wise in the Forkriver Crossing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66344] = { id = 66344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Wind at Our Backs", description = "So the Primalists have recruited Clan Nokhud as allies. \n\nWe have held off the Primalists until now, but the Nokhud have brought a new weapon: a dragonkiller ballista. I fear Solethus will not be the last dragon to fall to its foul storm magic.\n\nCome. I will take you to the dragons' haven at Shady Sanctuary. You can tell me what you know of the Nokhud while the Khanam Matra gathers her forces. We must prepare for our next move.", completion = "We have arrived, mortal. Welcome to the Emerald Gardens.", objectives = "Ride with Gerithus and Merithra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66349] = { id = 66349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Rock", description = "Remove those rocks!", objectives = "Remove 3 rocks", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66351] = { id = 66351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke Over the Mountain", description = "<Pathfinder Jeb looks at the mountain ridge beyond the camp and sniffs.>\n\nI don't like it. Pathfinder Yips should've been here days ago. Was gonna help me teach this new batch of explorers how to climb these pillars safely.\n\nNow I see smoke in the distance.\n\nI don't like it at all.", completion = "Ye're just in time. Pathfinder Yip is starting to lose her grip up there!", objectives = "Find Pathfinder Yip's plane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66352] = { id = 66352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Enemy Knows", description = "It is vital that we determine the Sundered Flame's mission in these ruins and how it relates to the arcane surge.\n\nWe'll do this the old fashioned way: reconnaissance and espionage.\n\nThe ruins are overrun with Sundered Flame devotees. I am sure some of them carry orders that may illuminate their mysterious goals.\n\nUse any means necessary to obtain these documents.", progress = "Have you found anything yet, {name}?", completion = "Thank you, {name}. I am humbled by your skill and efficiency.\n\nMaybe I'm not the only one who will be a \"good influence\" on Rannan.\n\nNow... let us find out what the Sundered Flame is doing here.", objectives = "Find Sundered Flames documents and bring them to Lathos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66353] = { id = 66353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "R.A.D. Anomalies", description = "There is a LOT of arcane energy here...\n\nBut! The R.A.D. can help with that! It's an awesome device--it's right in the name: \"Rannan's Awesome Device!\" It detects AND dispels arcane energy.\n\nHere... hold it! Do you feel the POWER in your hands? No?\n\nWell, now that you've got it, take it and dispel those anomalies!", progress = "Go! Go! That arcane energy is not going to dispel itself.", completion = "Hm... You dispelled the anomalies, but the R.A.D. still detects an arcane surge... and it's rising by the minute.\n\nThat... can't be a good thing.", objectives = "Use the R.A.D. to dispel three arcane anomalies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66354] = { id = 66354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spark", description = "The forge is ready. All it needs now is flame.\n\nPlace the damaged Oathstone fragments upon the forge, and Wrathion shall provide the spark to ignite the process.", progress = "Have the fragments been reformed?", completion = "The damaged pieces of the Oathstone are repaired! This is only the beginning of what can be accomplished here!\n\nWith the forge re-ignited I can begin the process of crafting new weapons and armor to aid our efforts.", objectives = "Reform the damaged parts of the Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66356] = { id = 66356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irontree" }
quests[66363] = { id = 66363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisk Bucklers", description = "Interlinked scales are the key to stopping an arrow. The bucklers we make are the best in the plains. However, I am short of basilisk hides for my next order. \n\nI see you are interested in learning about our crafts. Gather basilisk hides from around the Dragon Isles, and I will give you instruction on our techniques.", progress = "Do you have the hides?", completion = "These are of excellent quality! You have my thanks.\n\nFor your help, please take some of the extra leather we have in our stores. I can also give you some insight about your trade, as I promised.", objectives = "Gather 20 Rigid Basilisk Hides from the basilisks of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66364] = { id = 66364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fly a Kite", description = "Let me tell you about an opportunity.\n\nThe proto-drakes and proto-dragons have an amazing range of motion on their wings. And the ribbing! It is so extendable. We mostly make our kites from stretched hides. With the proto-drakes causing havoc, I was wondering if you could return some of their wings to me? I can make kites that would be the envy of the tribe.", progress = "Do you have the wings?", completion = "These will work masterfully. I will have a working kite fashioned in no time. \n\nOh, and for all your help, let me give you some insight to your trade. It is the least I can do.", objectives = "Gather 10 Fresh Proto-Dragon Wings from the proto-drakes and proto-dragons of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66368] = { id = 66368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island In A Storm", description = "There has been little time to rest. The elementals' assault is relentless!\n\nA moment of respite would be welcome and allow me to craft more wards for our defense.\n\nSee what you can do to thin out the onslaught on our perimeter.", progress = "They must be culled.", completion = "It was a welcome moment of rest. In return I have a gift for you.", objectives = "Eliminate 10 Blazing Manifestations and Melter Igneous.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66369] = { id = 66369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen Ward", description = "I have empowered a ward using the rings you collected. It has gathered the very stones of the earth around it and created a Living Earthen defender to protect this territory.\n\nTest the Earthen Ward to ensure it's functional.", progress = "Was the test successful?", completion = "Thank you for your aid, {name}. I will place more of these wards throughout the area to combat the djaradin and the elementals. Use these charms to activate them when you need assistance.", objectives = "Activate the Earthen Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66383] = { id = 66383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Assistance", description = "{name}, we have convinced the Enlightened Brokers to provide additional supplies for the battle against the Jailer!", completion = "Welcome. Please view my wares, several of which can assist you in the crafting of Legendaries!", objectives = "Visit Vilo, the Enlightened Quartermaster, to see what is available.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66390] = { id = 66390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Merchandise", description = "Hmmph, those sea-brained Seabraids are off on another adventure, and I'm stuck here sifting through their goods!\n\nAh, maybe I'm a bit bitter, but I do wish Tawny could be a bit more brief. I don't need a novel, just some instructions is all. And on top of it all some of the merchandise has disappeared, along with one of my workers! \n\nWould ye mind gettin' it back for me? I'm sure ye could tempt him with an exchange of a drink, or throw this at him if ye can't.", completion = "Ah! Ye got seawater on the merchandise! Ah well, I don't think the Seabraids will mind too much... long as it's intact.", objectives = "Retrieve the stolen goods from the thief at the Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66391] = { id = 66391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Ruins!", description = "Are you interested in hearing about my invention, the R.A.D.? No?\n\nWell, I'll tell you anyway--because it found something.\n\nToday it detected a HUGE SURGE of arcane energy from the Karnthar Ruins. Lathos thinks the Sundered Flame are to blame. It's the PERFECT opportunity to showcase the R.A.D.!\n\nWanna come? It's going to be awesome.", completion = "You missed it! We walked RIGHT into a Sundered Flame patrol. \n\nLathos SLASHED through them, but there were too many!\n\nSo, I started casting arcane explosions left and right... KAPOW! ZING!\n\nOh, but um, yes... the energy surge...", objectives = "Meet Rannan and Lathos in the Ruins of Karnthar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66392] = { id = 66392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying Nature's Allies", description = "We cannot give into despair now. We must push forward. We must think of another way through the barrier.\n\nFirst, we need our allies. Countless elementals summoned by Rymek are pouring through the portal. We will need an army that can move in the Dream like we can, or one that can be brought in easily.\n\nRally the druids and centaur in Shady Sanctuary. It is time to call upon their oaths to preserve the grove.", progress = "Are you ready to cross to Ardenweald?", completion = "I will go with you into Ardenweald. I will tell Ysera that we need her back, and we know a way to do it. \n\nI should be the one who makes this sacrifice. I've lived a long life. I never wanted to live longer than my son. This way, I can atone for Rymek's betrayal and bring back our Aspect.\n\nAre you with me?", objectives = "Muster the druids and gather the empowered anchors in Shady Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66393] = { id = 66393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Somnikus", description = "Somnikus has been melancholy and agitated since the death of his son.\n\nThough we have all endured loss, I cannot imagine what I would feel were something like that to happen to Gerithus.\n\nGo with Rymek to the isle, and see if there's anything we can do. Somnikus suspects that the Primalists are on the verge of another attack. I fear that he may do something rash.\n\nDo not worry. Because of your help with the Emerald Oathstone, you can cross the barrier easily.", completion = "Welcome to Ancient Bough, young one. \n\nDid Merithra send you to check on me? I am far too old for her to be worrying about me.", objectives = "Meet Somnikus with Rymek near the Oathstone in Ancient Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66394] = { id = 66394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thin the Veil", description = "There must be a way to lower the barrier from within this grove. I sense several points around us that strengthen it.\n\nIf you can deactivate enough of those, we should be able to lower it the rest of the way so the others may join us.", progress = "Have you found the barrier moorings?", completion = "That should do it. The barrier is about to come down. \n\nSoon the others will be able to join us in the Emerald Dream, and we can fight together again.", objectives = "Deactivate Barrier Moorings in Ancient Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66395] = { id = 66395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chittering Rocks", description = "Merithra needn't worry about me. I'm fine. My son's death... I'm fine.\n\nIf you really want to help put my mind at ease, there is something you could do. I suspect Primalists will try to invade these lands again. Unlike last time, I doubt they'll attack the Ancient Bough directly. They know we'd defeat them.\n\nSee those rocks over there? Those off-color, slightly smelly rocks? I hear something moving underneath them. Perhaps Primalists are lurking nearby! Could you investigate? Squash whatever you find.", progress = "I can hear them skittering around under the rocks. Who'd dare to summon creatures like that so close to the portal?", completion = "I knew there had to be something there. And to think, they were so close to the portal. Now I can contemplate... other things.\n\nWhile you were hunting, Rymek and I had a lovely conversation. He's quite understanding and sympathetic. In a way, he reminds me of Solethus...\n\nHe asked if he could see the portal to the Emerald Dream with his own eyes. I see no reason why not, especially since you've cleared those spiders away. I'm sure he'll be quite impressed.", objectives = "Investigate Suspicious Permafrost and slay Glacial Tunnelers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66396] = { id = 66396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guarded Appreciation", description = "I know it can be quite exhausting work to defend such an important locale. And often, we drakonids and dragonspawn get very little thanks for our dedication.\n\nI wish to bestow some of my own appreciation to the guards here in Ancient Bough.\n\nHere, offer them these gifts from me, as a sign of friendship. I hope my heartfelt gesture properly expresses my gratitude.", progress = "Have you given the guards my gifts?", completion = "Very good. I hope they like those gemstones. I made them myself, just for this special occasion.", objectives = "Give 6 guards Rymek's Gift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66397] = { id = 66397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Full Strength", description = "We need reinforcements, and quickly. But Merithra cannot yet join us in the grove because of the barrier. We will need to manage both from here within the Dream.\n\nSlay these Primalists and take anything you need from them, so we can melt those ice prisons and free the grove guards.", progress = "That was too cold. Close. Too close.", completion = "Thank you for breaking me out! I can't believe that Ysera is actually here, back in the Emerald Dream! Just like in my theory. \n\nI'd dearly love to ask her ten thousand questions, but I have to focus. There's still the problem of Rymek.\n\nAnd I saw where he was headed, too, just as he caught me in ice.\n\nHe's after something in the Dream, something powerful. I don't know what, but we have to reach him before he finds whatever it is!", objectives = "Free Emerald Scaleguards and Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66398] = { id = 66398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Dragonflight", description = "If we are to eradicate the Primalists from the Emerald Dream, the one place we must secure is Lunedane. According to my son, that is where Rymek has gone.\n\nIt is the last line of defense for the nascent Tree. There, an ancient artifact shields the Tree from being found. And, it is powerful enough to expel all our enemies at once.\n\nI do not know if my mother has the power to command and use it anymore. But we will deal with that once we have found and stopped Rymek.\n\nFly with us, as one.", completion = "We've made it. But Rymek has already started his assault. We can't let him break through!", objectives = "Speak to Gerithus, and fly with Merithra and Ysera to Lunedane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66399] = { id = 66399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We'll Cross that Bridge", description = "We have to do something about this snow! If we're to give you proper support against Rymek and his minions, we can't have our wings freezing off.\n\nI sense powerful Frost Cores nearby. They're probably sustaining this blizzard. If you can destroy them, we can take out Rymek's minions in short order.\n\nAnd Somnikus is out there too. He flew off for Rymek like a dragon possessed. We need to get to him as soon as we can.", progress = "Everything hurts.", completion = "<Somnikus's breathing is labored and pained. He shivers with cold.>\n\nI held him off... as long as I could.", objectives = "Destroy the Frost Cores and reach Somnikus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66400] = { id = 66400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winter's Fall", description = "<Somnikus struggles to breathe as he slowly freezes.>\n\nI managed... to stop him from reaching the tree. I hope it was enough.\n\nRymek must fall, now. It is up to you.\n\nTell Ysera and Merithra that I am sorry... for being a foolish old dragon.", completion = "Rymek is defeated, but there are still too many elementals and Primalists roaming through the Dream.\n\nI suppose... now we find out who the Dreamer really is.", objectives = "Defeat Rymek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66401] = { id = 66401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamer", description = "We have fought so hard to reach this point, and only one thing remains. The power in Lunedane will only respond to someone who can command the Emerald Dream from within.\n\nI had thought that it could only be my mother, but... I see how she has changed. \n\nI do not know if that difference is better, but it is real and I must acknowledge that.\n\nCome, let us face this moment together.", completion = "I am the Dreamer.", objectives = "Unleash the power of the Dream Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66402] = { id = 66402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Mother, Like Daughter", description = "From the moment I stepped into the Dream again, I knew that things were different. But now that we have beaten Rymek and his Primalists, I must consider all of the implications of what has happened.\n\nMy daughter has worked to keep the green dragonflight together after my death. It is only fitting that she be the one to ascend now. \n\nMerithra must lead the Emerald Flight.", progress = "I am ready. I must be.", completion = "Where my mother once flew, I must fly now and in the future. Where her breath brought peace and life, so must mine.\n\nI pledge that I will do my best as the leader of the green dragonflight. I promise that I will do whatever it takes, as Ysera did for so many millennia.", objectives = "Witness the ascension of Merithra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66409] = { id = 66409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Matters", description = "The chieftain is not taking visitors.\n\nWhether Iskaara sent you or not, we're dealing with our own share of trouble right now. We don't need outsiders bringing more of it.\n\nIf you want our time, make yourself useful and help our guards. The djaradin have been attacking us from across the river. Flameshaper Lorak is behind the assault. He may not look like much as far as djaradin go, but he's got more brains than the rest of them.\n\nDeal with him and bring back proof. Then we'll talk.", progress = "If that weapon's just for show, tell us now so we don't waste time.", completion = "I'll admit I didn't expect you to come back alive.", objectives = "Collect a trophy from Flameshaper Lorak at Scalecracker Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66410] = { id = 66410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worst Impressions", description = "<Hakota turns the trophy over in his hand before clasping it. He grimaces.>\n\nSo this is what we've been reduced to. An outsider does more work for us in a day than our chieftain has in weeks.\n\nCome. I will take you to him.\n\nMaybe this will be the kick in the stern that he needs.", progress = "What do you seek to take from us?", completion = "<Tutaqan tosses the trophy on the ground nearby, tired and disinterested.>", objectives = "Speak to Tutaqan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66411] = { id = 66411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubled Waters", description = "It saddens me to see our chieftain like this, but our needs cannot wait.\n\nThe river has provided for us for generations. But as the djaradin push forward, the waters recede, and the creatures fight with each other for space and resources. \n\nWithout guards, our anglers cannot venture far to fish. Our food stores dwindle by the day.\n\nYou do not seem to need protection though. Take this net to help gather any fish you can from the river. Meat from the nearby crabs would also be welcome.", progress = "The river was once beautiful and its bounty plentiful. I pray that its gifts will return to us one day.", completion = "At least our children will not go hungry while our chieftain neglects his duties. Thank you, {name}.", objectives = "Gather 10 Warmwater Riverfish and 6 Succulent Snapper Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66412] = { id = 66412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carry On, Basilton", description = "There is one more thing this old drakonid would like to ask you, before you leave.\n\nBack when Lord Basilton and I first met, we would go on all sorts of adventures together. I think that's why he wanders off. He misses exploring.\n\nI can't do that for him anymore. But you can! You can take him to see places I never would have dreamed of, I can tell.\n\nHowever, we should ask Basilton what he thinks first.", progress = "Let's see what Basilton thinks.", completion = "I'm jealous of him, if I'm being honest. To be young again, and exploring the world. You'll have to visit, sometime, so you can tell me what he's been up to.", objectives = "Speak with Basilton in the Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66413] = { id = 66413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Heat", description = "<This fish has clearly been dead for some time.\n\nUpon closer inspection, you notice that it appears to have been boiled--probably while still alive in the river.\n\nUnujaak back at the village might be interested in this.>", completion = "Oacha'noa preserve us! How my heart aches to see the river disturbed in this way. \n\nThis must be yet another of the djaradin's atrocities. Their fiery magic has been heating the river beyond anything these poor creatures can endure.\n\nBut it would be disrespectful to allow this one to go to waste. Go on, throw it in the pot. We will use it for tonight's meal.", objectives = "Take the Half-Boiled Fish to Elder Unujaak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66414] = { id = 66414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All But One", description = "I have seen what you've done for the village. In easier times, I would have handled it, but...\n\n<Tutaqan glances towards the river, then back to you.>\n\nSome of our ottuks went missing recently. We believe they swam too close to the djaradin's territory. Several were recovered. None of them alive. Few in one piece.\n\nWe could not find my ottuk, Ipko. She has been my hunting partner for many years. If she...\n\n<He shakes his head.>\n\nPlease... aid me. If you search the river, I will search the shore.", progress = "I shouldn't have let her wander so far...", completion = "This is my fault.", objectives = "Find Ipko.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66415] = { id = 66415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way Past Is Through", description = "Unujaak told you to come, didn't he? He was the one who helped me find Ipko when I became a hunter--or, rather, helped Ipko find me. They choose and we are chosen.\n\nHe is hurting. Everyone is hurting because of me. I know that they need me to lead, but I have been half of a leader without her. If I couldn't protect her, how can I protect all of Uktulut?\n\n<He takes a deep breath.>\n\nI cannot forgive myself. But I cannot let that weight keep me from putting at least one foot on the path I must walk.", progress = "I knew this would happen one day, though it does not blunt the pain.", completion = "Nothing will replace Ipko. But water can only fill hands cupped to receive it.", objectives = "Help Tutaqan find a new ottuk companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66417] = { id = 66417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging Supplies", description = "Bah! I can't believe Tutaqan's still moping around when we need him to command his guards and hunters!\n\nWe used to trade with the Iskaara at our pier, but that's gone belly up with the djaradin closing in and scaring off our traders. Half of last month's supplies and most of our boats are still lost out in the shallow river.\n\nThe guards and hunters want to help, but they've got no weapons. You look like you can protect yourself, so get out there and grab something I can make spears with!", progress = "Once our guards and hunters have new weapons, I can pull together a group to gather the rest of the wreckage.", completion = "It's about time! They're a little wet, but I'll be able to make many fine weapons with these.", objectives = "Collect 8 Whalebone Fragments and 30 Waterlogged Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66418] = { id = 66418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Tuskarrsenal", description = "The first weapon is ready! Soaking the bones in river water warmed by the djaradin's fire made them more pliable. I'll remember that trick!\n\nSince you've been helpful so far, I'll do you the honor of letting you test out some authentic Uktulut weaponry. You'll find no sharper blade or sturdier haft this side of the Dragon Isles.\n\nGo test this out in our training area for me. Maybe it'll remind the chieftain what real fighting looks like! Ha!", progress = "Our training area is just up the hill. Make sure those weapons are ready to crush some djaradin.", completion = "Haha! I heard that commotion all the way over here! \n\nIf that talk doesn't get Tutaqan moving again, I don't know what will.\n\nAt least our hunters will have all the weapons they need to defend our village, with or without their huntmaster's help. Thanks, {name}.", objectives = "Take the Uktulut Bone Spear and destroy 4 Tuskarr Training Dummies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66419] = { id = 66419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to One" }
quests[66420] = { id = 66420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happy Hour", description = "Now that the merchandise is back, it's time ta get everything else sorted out.\n\nWith everything going on some of my crew decided it would be okay to disappear for some extended meal times.  See if ye can find them and get them back here. \n\nWe can all celebrate AFTER the work is done.", completion = "Great job! Now that we're all back ta work we'll make good time.", objectives = "Throw briny seawater at 3 workers in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66421] = { id = 66421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Scar" }
quests[66422] = { id = 66422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Expedition Continues!", description = "An ancient site, an organization with inscrutable motivations--even Rannan's R.A.D and its analyses... \n\nIt all stirs the explorer in me.\n\nWe must discover more about what's going on here.\n\nThere are stairs to the south leading up to a tower. We shall press on.", completion = "These Sundered Flame did not die by my hand... or by Rannan's \"signature move.\" \n\nThey were dead when we arrived. \n\nRannan believes they suffered multiple traumatic wounds caused by arcane energy.\n\nI agree with his observations. But it's unclear if it was the dragon console discharging or friendly fire...", objectives = "Meet Rannan and Lathos by the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66423] = { id = 66423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worries and Validations", description = "The deaths of these Sundered Flame underscore how dangerous the Ruins of Karnthar are.\n\nBut Rannan believes that with some tinkering the R.A.D. can still quell the energies here.\n\nAgain, we're treating the symptoms and not the root cause.\n\nSearch the ruins for clues and see if you can discern their original function. And make haste, {name}. We may not have much time.", progress = "Were you able to learn anything about the ruins?", completion = "This is... not good news.\n\nIf Sindragosa could not control Karnthar and ordered this station abandoned, I can only imagine the nefarious things that the Sundered Flame could do with it.\n\nWe must not let it fall into their hands.", objectives = "Find clues about the origin of the ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66425] = { id = 66425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Overload", description = "There! Finished!\n\nMay I present to you... the R.A.D.D.E.R!\n\nDUN DUN DUUUUN! \n\nI have calibrated it to the frequency of the energy surrounding the dragon consoles and inscribed a glyph of dispel magic on it.\n\nThe R.A.D.D.E.R. will dispel the arcane energy and shut down the dragon console, but the glyph will weaken after each use.\n\nPretty handy, isn't it?\n\nI detect four of these consoles in our vicinity. Go shut them down!", progress = "Were you able to dispel all the arcane bubbles with the R.A.D.D.E.R.?", completion = "You've done it {name}!\n\nWell, you and the R.A.D.D.E.R...\n\nBut whatever... Now, help me get Lathos back to Camp Nowhere.", objectives = "Help Rannan dispel the arcane bubbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66426] = { id = 66426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Out of Time", completion = "This is worse than we thought. The arcane energy is almost at its peak.\n\nSomething is hastening the process.", objectives = "Reach the east tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66427] = { id = 66427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Looming Menace", description = "The arcane wounds I suffered cannot be healed in the field. I am afraid that they are too grave for me to fight. \n\nI must ask your help again, {name}.\n\nYou have to find Tharohn and stop her from overloading more consoles. \n\nDoing so would buy Rannan a few precious moments to calibrate the R.A.D. ... R.A.D.D.E.R... whatever he's calling it now. \n\nMaybe then we can thwart the Sundered Flame's machinations.", progress = "Do not waste a moment. We are on borrowed time.", completion = "It is done then.\n\nNow it is all on Rannan. I trust his abilities. They have gotten us this far...", objectives = "Kill Tharohn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66428] = { id = 66428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friendship For Granted", description = "Alright! The R.A.D.D.E.R.E.R is calibrated and ready to go--for you!\n\nWhy am I not using it? Simple! \n\nYou have to think of and consider all the possibilities. \n\nLet's say it blows up. Who would fix it if I am injured, unconscious, or dead? Could you imagine? \n\nNow, go dispel the barrier so we can return to camp and get Lathos patched up. I'll be... standing back.", progress = "Is this day going to get any better?", completion = "Just like that he's... gone?\n\nHe gave his life to save us because the R.A.... the machine didn't work.\n\nLathos believed in me... I should have listened... I let him down...", objectives = "Use the R.A.D.D.E.R.E.R to dispel the arcane barrier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66429] = { id = 66429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Will Remember", completion = "It was only at the very end that I began to appreciate Lathos. I took his patience and experience for granted.\n\nWe owe him our lives.\n\n<Rannan looks towards the Ruins of Karnthar.>\n\nI will never forget him.", objectives = "Meet Rannan outside of Camp Nowhere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66431] = { id = 66431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Mourning", description = "This did not need to happen. Those cowardly djaradin... slaughtering our ottuks and leaving them for their twisted beasts to pick clean...\n\nI do not take Tutaqan's grief lightly, but I worry for the future of our people if he dwells in darkness and grief for too long. \n\nWe need to act.\n\nIt looks like he was headed to the overlook above us. You have done him a great favor this day. He may be open to any good will you can show him. Please, see what can be done.", progress = "Please leave me be.", completion = "<Tutaqan rubs his face with both hands, sighing deeply. He looks haggard.>", objectives = "Attempt to help Tutaqan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66435] = { id = 66435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Site Salvage", description = "I've worked with many elementals as a shaman, but I've never seen any this aggressive!\n\nThe Expedition discovered a titan vault here, but a barrier protects the inner chamber. When we tried to dispel the barrier, I think we triggered some kind of security system... There were suddenly angry elementals everywhere!\n\nMany explorers were working in the dig site when the elementals attacked. Many of them are trapped, and NONE of them are fighters. \n\nPlease go down into the dig site and help them retreat!", progress = "I am only a consultant for the Expedition, but I care for the explorers I've met here. We can't leave any of them behind!", completion = "Everyone's safely within our new perimeter. Thank you, {name}.", objectives = "Rescue 5 Beleaguered Explorers in Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66436] = { id = 66436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Troublemakers", description = "The earth elementals are not just trying to repel us, they're destroying artifacts and equipment, too! It's as though they've been programmed to destroy anything titan...\n\nWe're holding them off, but we can't continue to study this site while they're here. Please help us push them back so we can have some exploring room!", progress = "The elementals caught us by surprise! Be careful!", completion = "That should be enough to solidify our position here. Good work, {name}.", objectives = "Kill 12 Earth Elementals in the Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66437] = { id = 66437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Key Element", description = "<This orb of earth thrums with energy.>\n\n<Elementalist Taiyang might know what to do with it.>", completion = "I can feel the elemental energy stored within this orb. You may have found a solution to our troubles here.", objectives = "Return the Orb of Primal Stone to Elementalist Taiyang in the Life Vault Ruins.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66438] = { id = 66438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lofty Goals", description = "Air is a powerful element. It cuts through stone and fills sails to take us where we need to go.\n\nMy hypothesis is that air will be the most effective at removing this barrier. It's simple, really.\n\nMy scouts report they've found the Orb of Primal Gales. Scout Ri'tal can lead you to it. You can find them near Hornswog Hollow. Quickly!", progress = "Have you found the scout?", completion = "Tae'shara stays above many tasks, preferring to delegate. I can see why the Orb of Primal Gales interests her. I'll hold onto it for now.", objectives = "Find Scout Ri'tal in Hornswog Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66439] = { id = 66439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rapid Fire Plans", description = "Elemental orbs, eh? If there's earth, there's bound to be fire!\n\nThe primalists over near tae hornswog nests are reshapin' tae land with lava. If anyone has an interest in tae Orb o' Primal Flames, it'd be them!\n\nTake them out and see if they have anythin' useful!", progress = "Acadia had a lead on the Orb of Primal Flames. Have you found it?", completion = "Ah, the Orb of Primal Flames. It is as vibrant and fiery as Acadia. I will hold onto it for now.", objectives = "Collect Primal Flame Fragments from Primalist Forces in Hornswog Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66440] = { id = 66440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closure", description = "I do not know what to say. I had no idea that the chieftain's pain ran so deep.\n\nIt makes sense. Ottuks are not pets to our people--especially not to hunters like our chieftain. They are our friends, our companions... and members of our families.\n\nIpko was Tutaqan's first and only ottuk. Uktulut hunters hold this bond to be sacred.\n\nI will see that her passage to the place of our ancestors is a peaceful one.", progress = "This is all I can do.", completion = "<Tutaqan's jaw is set tightly, tears brimming in the corners of his eyes. He does not look at you.>", objectives = "Speak to Tutaqan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66441] = { id = 66441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distilled Effort", description = "The Orb of Primal Stone is a fortuitous find, but Acadia and Tae'shara have conflicting hypotheses regarding the barrier.\n\nI have my own hypothesis. Perhaps with more elemental orbs an answer will become clear.\n\nOne of the explorers saw an oversized water elemental in a nearby cave. Defeat the elemental, and perhaps you will find another orb.", progress = "Did the elemental have another orb?", completion = "We must be like water: ready to adapt. Thank you for bringing the Orb of Primal Waves to me.", objectives = "Kill Acequian in the cave east of the Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66442] = { id = 66442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Get Theoretical", description = "We now have four elemental orbs! Let us see which hypothesis proves fruitful.", completion = "My original hypothesis stands firm. The elements are more effective together.", objectives = "Help test the orbs against the Titan Barrier in Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66443] = { id = 66443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling the Hunting Party", description = "<The resounding call of a hunting horn rumbles from the center of the village, calling the Uktulut hunters to attention.\n\nYou should investigate.>", progress = "This could be our only chance to hit them where it hurts!", completion = "If the chieftain doesn't take care of the job, I'll smash that djaradin to pieces myself. Mark my words.", objectives = "Investigate the reason for the hunting call.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66444] = { id = 66444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While the Iron Is Hot", description = "I spoke to our lookouts on the way down. They say this djaradin--Zhurtan the Riverboiler--has begun his heinous ritual southwest of here, close to the waterfalls where many of our ottuks build their nests.\n\nIf they're boiling the river upstream from us now, I assume they've decided to be done with us more quickly. We would be forced to starve or retreat. We will do neither.\n\nThey've prodded us like cowards afraid of a true fight. So let's bring the fight to them this time, shall we?", progress = "We have your back, as you have ours.", completion = "Our river--and our people--could not have been saved without your help. \n\nThe Uktulut tribe owes you a great debt.", objectives = "Slay Zhurtan the Riverboiler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66445] = { id = 66445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Our Fallen", description = "The djaradin have no regard for the sanctity of the Citadel or the bodies of our kin! They break the bones of the dead and take their personal keepsakes as souvenirs.\n\nThis disrespect cuts at the heart of every proud black dragon. They deserve honor. \n\nRecover these items that the djaradin have stripped from the bodies of our fallen.", progress = "Have you recovered the items of the fallen?", completion = "The memory of those who fell will not be lost. No thanks to the djaradin.\n\nThese items will be kept safe and we will remember the dead.", objectives = "Recover 8 Fallen Defenders Ring, 3 Earth-Warder's Flame Blade and 1 Horn of Scorxia", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66447] = { id = 66447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Barrier", description = "Now that the barrier is down, let us explore the vault!", progress = "There's a lot to examine in the vault, but we should start small to be safe first!", completion = "I think we'll be alright now, {name}. Thank you. It's time for the Expedition to dig deeper!\n\n\n\nJust a little shaman humor. Too soon?", objectives = "Investigate the Life Vault in the Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66448] = { id = 66448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Waywatcher", description = "The Waywatchers have kept the roads of Thaldraszus safe for travelers for as long as I can remember. It is a duty that my family has upheld with honor for generations.\n\nAlas, my sister Alvi seems less than interested in that honor of late. She is supposed to report to me here each morning, but I have not heard from her in over a day. \n\nIf you find a bronze drakonid east of here, lazing about with her head in the clouds, I ask that you direct her to me. Otherwise, I will have to seek her out myself.", completion = "Oh, gracious, a traveler. Please forgive me, I am a bit of a mess at the moment.", objectives = "Find Waywatcher Alvi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66449] = { id = 66449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands-Off Operation", description = "Qalashi dustbinders are trying to imprison our whelps. It seems their leader is planning to use them for some nefarious purpose. We cannot let this happen!\n\nBut the djaradin are not the only enemy here. Phoenixes are also tracking our whelps, presenting even more danger. \n\nYou must protect the the whelps and eliminate the enemies that threaten them. Osoria will assist you.", progress = "Have you eliminated the threats?", completion = "Even the smallest black dragon whelp must be protected. Our future depends on it.\n\nYou have accomplished great things today.", objectives = "Save 8 Endangered Whelps while eliminating 12 Searclaw Phoenixes and Ashbinder Tornecha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66456] = { id = 66456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poisonous Palette", description = "I may not be great at my job, but at least I paid attention when I was learning how to do it. Every Waywatcher worth her scales knows how to make a proper antidote. I just need enough poison to mix it properly.\n\nNori said the tarasek who attacked her had spears coated with the stuff. Find them and bring their spears to me. If my hunch is correct, I'll be able to make an antidote with the residue from the spearheads.\n\nI just hope we have enough time.", progress = "Please hurry, {name}. I am keeping Nori stable for now, but the poison is still spreading.", completion = "<Alvi takes the spears that you gathered. She carefully scrapes her dagger across one of the blades, removing a film of sticky, sickly sap.>\n\nIt's just as I thought. Thank you, {name}. This should be enough for an antidote, and I even think I know where the poison is coming from.", objectives = "Gather 8 Envenomed Spears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66457] = { id = 66457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Blue Period", description = "The Embertooth all follow an oversized brute that I've taken to calling Bluescale. He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now.\n\nBluescale has to be responsible for this sudden escalation. Find him and take him down.", progress = "Be careful, {class}. Bluescale is tougher than your average Tarasek scavenger.", completion = "With Bluescale taken care of, I doubt we will have to deal with any organized tarasek encroachment any time soon.\n\nNow all that's left is to deal with the poison.", objectives = "Slay Bluescale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66458] = { id = 66458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", progress = "Did you retrieve the disc?", completion = "Infinite dragons? Their kind always has some kind of plan.\n\nI will inform the Dragon Queen that she will have to find some other way to restore the power of the Aspects.", objectives = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
